t","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/302f42c7-2c06-47de-a5ef-6d2940d026bf/portrait/1790318633853-terrax-character-portrait.png","relationships":{"allies":"","rivals":"Ignis","enemies":"","mentors":"","parents":"","partner":"TBD","children":"Ruchicka — Oldest child and Bone Dragon\nGaius — Sand Dragon\nShailara — Youngest child and half-Sylvani Stone Dragon","siblings":"","worldConnections":"Shuǐmǔ Lánhuá — Mother of Ruchicka\nAetheros — Mother of Gaius\nEldoria — Homeland of Shailara''s Sylvani family\nStone Mountains — Personal sanctuary\nHeavy Grumble — Devoted human followers\nIronspire Hold — Independent Duroc homeland","relationshipNotes":"Ruchicka is Terrax''s oldest child with Shuǐmǔ Lánhuá and lives primarily with Terrax while maintaining ties to his mother''s water domain. Gaius is Terrax''s child with Aetheros and lives with his father while maintaining ties to his mother''s air domain. Shailara is Terrax''s youngest child, born to a Sylvani elf; she lives with Terrax while remaining connected to her mother''s people in Eldoria."},"spoiler_level":"private","race_record_id":"f0c6ce62-f547-4fc2-8765-6a9f8bebc590","realm_record_id":"53d924ac-f33c-491b-a246-240d886c2de5","workflow_status":"draft","family_record_id":"cc24abab-518b-4ef0-8cbe-dbea119ee873","faction_record_id":"0ba48458-c018-47e8-bfc0-bcfcd31aa531"}','2026-09-25T16:18:09.187254+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('08dafb07-2eb6-4078-bcc6-71a093746e61','studio_characters','7538e2ae-03cd-4c2f-a116-05e51b4fa245','Ruchika','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"7538e2ae-03cd-4c2f-a116-05e51b4fa245","name":"Ruchika","media":{"tbdFields":"Exact age\nBirth date\nExact birthplace\nExact weight\nDominant hand\nName meaning\nNationality\nRomantic partner\nPermanent enemies","canonLocks":"Ruchika is the Bone Dragon\nMale\nSon of Terrax and Leviathans\nEarth + Water heritage\nBrother of Gaius\nBrother of Ife\nBrother of Rahim\nLives in the Shifting Sands with Gaius\nRuchika is a wanderer\nRuchika is a master craftsman\nRuchika crafted Ife''s Bone Dragon Whip\nRuchika is not missing\nRuchika does not have memory loss\nTrue form uses an ivory bone exoskeleton\nDragon wings have water-like membranes","galleryUrl":"","mediaNotes":"Human and dragon references should preserve the same ivory, midnight blue, slate gray, earth brown, black, and golden amber palette.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7538e2ae-03cd-4c2f-a116-05e51b4fa245/portrait/1790317260638-ruchika-s-character-portrait.png","visualAssets":"Official character portrait — Needed\nFull-body front view — Needed\nBack view — Needed\nLeft view — Needed\nRight view — Needed\nFace reference — Needed\nHair reference — Needed\nOutfit breakdown — Needed\nBone weapon reference — Needed\nTrue Bone Dragon Form — Needed\nCombat reference — Needed\nBone Dragon Whip — Done","productionNotes":"Keep his silhouette tall and grounded. Bone should be modeled separately from skin and clothing so it can emerge, retract, break, and regenerate during animation.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7538e2ae-03cd-4c2f-a116-05e51b4fa245/reference/1790317393231-ruchika-s-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7538e2ae-03cd-4c2f-a116-05e51b4fa245/alternate/1790317539819-ruchika-s-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"TBD","era":"500–1300 AD-inspired fantasy era","name":"Ruchika","race":"Dragon","alias":"The Bone Dragon","gender":"Male","titles":"The Bone Dragon\nThe Ivory Artisan\nThe Wandering Craftsman","subrace":"Elemental Dragon","summary":"Ruchika is the Bone Dragon, born from Earth and Water. He is a disciplined craftsman, powerful defender, and natural wanderer who lives in the Shifting Sands with his brother Gaius.","heritage":"Indian + Asian","homeland":"Shifting Sands","pronouns":"He/Him","birthDate":"TBD","nicknames":"Ruchi","occupation":"Master Craftsman and Wanderer","affiliation":"Terrax and Leviathans bloodline","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"Major","pronunciation":"Roo-chee-kah","currentResidence":"Shifting Sands","elementalHeritage":"Earth + Water"},"abilities":{"weapons":"Manifested bone blades\nBone spears\nBone shields\nBone gauntlets","strengths":"Extreme durability\nPowerful defense\nRapid regeneration\nVersatile weapon creation\nExcellent battlefield control\nHigh physical strength\nSkilled craftsmanship","weaknesses":"Large constructs require more energy\nRepeated regeneration causes fatigue\nExtreme damage can slow reconstruction\nProtective instincts can be exploited","combatStyle":["Defensive combat","Counterattacking","Close-range combat","Battlefield control","Adaptive weapon creation"],"limitations":["Bone creation consumes energy","Density increases require concentration","Large-scale regeneration is exhausting","Cannot endlessly create massive structures"],"powerSource":["Bone Magic","Earth lineage","Water lineage","Draconic power"],"abilityNotes":"His bone is a living synthesis of Earth minerals and Water-driven regeneration. Broken constructs can pull themselves back together when enough of his magic remains.\n\nRuchika is not missing and does not suffer from memory loss. Those story elements belong to Rahim.","combatProfile":"Ruchika fights like a moving fortress. He absorbs pressure, controls space with bone structures, and changes his weapons according to the opponent.","weaponDetails":"Ruchika normally creates weapons directly from living bone. He can alter their shape, weight, flexibility, and density during combat.","transformations":"True Bone Dragon Form\nPartial Bone Armor","primaryAbilities":"Skeletal Replication\nBone Generation\nBone Manipulation\nDensity Manipulation\nInstant Bone Mending\nBone Weapon Creation\nBone Armor Creation","secondaryAbilities":"Enhanced durability\nEnhanced strength\nStructural awareness\nMineral sensing\nRapid bone regeneration\nHeat-resistant bone constructs","signatureTechniques":"Ivory Fortress\nSkeletal Bloom\nMarrow Forge\nBone Bastion\nIvory Lance\nLiving Arsenal","transformationDetails":"In his true form, Ruchika becomes a massive dragon covered in an ivory exoskeleton. Dark slate-blue skin shows beneath the armor, while translucent water-like membranes stretch between enormous bone wing digits."},"is_public":true,"appearance":{"build":["Tall","Lean-muscular","Broad-shouldered","Athletic"],"nails":[{"hex":"#C89B83","name":"Natural"}],"eyeHex":[{"hex":"#D89B32","name":"Golden Amber"}],"height":"Approximately 6''3\" / 190 cm","makeup":"","weight":"TBD","hairHex":[{"hex":"#151218","name":"Black"}],"skinHex":[{"hex":"#9A6548","name":"Warm Medium Brown"}],"eyeColor":["Golden amber"],"grooming":"Clean and practical","skinTone":["Warm medium-brown"],"wardrobe":"Travel outfit\nCrafting outfit\nCombat outfit\nCeremonial attire","hairColor":["Black"],"hairStyle":"Long layered hair worn loose","accessories":"Living bone bracers\nCrafting tools\nTravel satchel\nUtility belt","faceDetails":["Defined jawline","High cheekbones","Straight nose","Calm expression","Thick dark eyebrows"],"hairTexture":["Thick","Slightly wavy"],"colorPalette":"Ivory — #E8DFC8\nMidnight Blue — #182A3D\nSlate Gray — #4E5963\nEarth Brown — #654A3A\nGolden Amber — #D89B32\nBlack — #151218","dominantHand":"TBD","outfitColors":"Angrakha — Midnight Blue #182A3D\nDhoti — Charcoal #292A2D\nSash — Earth Brown #654A3A\nBone Bracers — Ivory #E8DFC8\nTrim — Muted Gold #B88A3D","alternateForm":["True Bone Dragon Form"],"clothingStyle":"Early-medieval Indian-inspired clothing with practical layered construction and bone accents.","appearanceNotes":"His design combines grounded Earth elements with subtle Water influence. Bone should always appear smooth, pale ivory, and organically grown rather than metallic.","outfitMaterials":["Woven cotton","Linen","Leather","Living bone"],"postureMovement":["Upright posture","Controlled movement","Heavy grounded stance","Quiet footsteps"],"signatureOutfit":"Dark layered angrakha with a wrapped dhoti, waist sash, living bone bracers, leather sandals, and practical crafting gear.","distinguishingFeatures":["Golden amber eyes","Long black hair","Living ivory bone","Bone can emerge from his body","Natural bone bracers"]},"created_at":"2026-09-25T05:08:38.036685+00:00","updated_at":"2026-09-25T06:40:42.613219+00:00","is_complete":true,"origin_lore":{"fears":["Failing to protect family","Losing control of his creations","Seeing his work used irresponsibly"],"goals":["Perfect Bone craftsmanship","Discover rare materials","Protect Ife","Continue wandering","Preserve useful knowledge"],"beliefs":["Strength should have purpose","Creation is as important as destruction","Nothing strong is built carelessly","Freedom and responsibility can coexist"],"culture":["Terrax elemental traditions","Leviathans aquatic traditions","Shifting Sands culture","Wandering artisan traditions"],"lineage":"Son of Terrax and Leviathans","storyArc":"Ruchika begins as a self-contained wanderer focused on craft and family. His travels gradually pull him into wider conflicts where his ability to create and protect becomes increasingly important.","backstory":"Born from Earth and Water, Ruchika developed Bone as his unique elemental expression. Rather than pursuing destruction, he became a craftsman who uses his power to build, repair, protect, and create. He eventually made his home in the Shifting Sands with his brother Gaius, but his wandering nature keeps him traveling throughout the Umbral World.","childhood":"Ruchika grew up between two ancient elemental bloodlines. Terrax shaped his patience and structural thinking, while Leviathans influenced the adaptive and regenerative nature of his magic.","lifestyle":["Lives in the Shifting Sands","Frequently travels","Crafts weapons and tools","Studies natural materials","Explores ruins and distant lands"],"storyRole":"A wandering Bone Dragon and master craftsman based in the Shifting Sands. His travels allow him to appear across many regions of the Umbral World.","birthplace":"TBD","psychology":["Values stability","Shows love through actions","Needs personal freedom","Protective of family","Finds peace through craftsmanship"],"motivations":["Protect his family","Master his craft","Explore the Umbral World","Understand unusual materials","Create objects that endure"],"personality":["Calm","Disciplined","Patient","Protective","Observant","Independent","Reserved","Reliable"],"voiceSpeech":["Low calm voice","Measured speech","Rarely raises his voice","Prefers direct statements"],"likesDislikes":["Likes craftsmanship","Likes quiet places","Likes traveling","Likes durable materials","Likes learning new techniques","Dislikes waste","Dislikes reckless destruction","Dislikes unnecessary conflict"],"majorLifeEvents":"Born to Terrax and Leviathans\nAwakened Bone Dragon magic\nBecame a master craftsman\nSettled in the Shifting Sands with Gaius\nCrafted the Bone Dragon Whip for Ife\nBecame a frequent wanderer"},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/7538e2ae-03cd-4c2f-a116-05e51b4fa245/portrait/1790317260638-ruchika-s-character-portrait.png","relationships":{"allies":"Gaius\nIfe\nTerrax\nLeviathans","rivals":"","enemies":"","mentors":"Terrax — Earth and structural discipline\nLeviathans — Fluidity and regeneration","parents":"Terrax — Father\nLeviathans — Mother","partner":"","children":"","siblings":"Gaius — Brother\nIfe — Sister\nRahim — Brother","worldConnections":"Shifting Sands — Home\nTerrax — Paternal connection\nSunken Dominion — Maternal connection\nUmbral World — Wandering territory","relationshipNotes":"Ruchika lives in the Shifting Sands with Gaius and shares a strong brotherly bond with him. He is especially protective of Ife and personally crafted the Bone Dragon Whip for her. Rahim''s disappearance remains a concern for the family."},"spoiler_level":"private","race_record_id":"1ec72d01-822b-4992-9434-7772a6b4e474","realm_record_id":"48066562-cd1c-4b72-8c29-399594efad38","workflow_status":"draft","family_record_id":"fc49b3d1-6cee-431a-8881-6a0873d53804","faction_record_id":"b17917f0-1e8d-4ecf-b622-61a143f39f32"}','2026-09-25T16:19:45.097434+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('93cabf8a-f94e-4814-be6d-41ade563acf0','studio_characters','838c6109-b23b-4fb2-aba6-af377de4497c','Ife','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"838c6109-b23b-4fb2-aba6-af377de4497c","name":"Ife","media":{"tbdFields":"The following details have not been permanently locked and may be changed as her story develops.\n\nIdentity / Timeline\n\nExact chronological age: TBD\n\nBirth date: TBD\n\nBirth year: TBD\n\nExact calendar system: TBD\n\nExact historical placement within the 500–1300 AD-inspired timeline: TBD\n\nPhysical Measurements\n\nWeight: TBD\n\nExact body measurements: TBD\n\nHer general athletic/curvaceous body type is established, but exact numerical measurements are unnecessary unless required for 3D production.\n\nRelationships\n\nRomantic Partner: TBD\n\nLove Interest: TBD\n\nChildren: None currently established\n\nFuture Descendants: TBD\n\nNamed Best Friend: TBD\n\nNamed Personal Friends: TBD\n\nPersonal Arch-Enemy: TBD\n\nAdditional Rivals: TBD\n\nStudents / Apprentices: TBD\n\nStory\n\nExact circumstances of Ife''s birth: Expandable\n\nDetailed childhood chronology: Expandable\n\nExact response to Rahim''s disappearance: Expandable\n\nRole in searching for Rahim: TBD\n\nFirst meeting with Ash: Not yet established\n\nInitial reaction to discovering Ash is her brother: TBD\n\nLong-term relationship with Ash: TBD\n\nMajor personal antagonist: TBD\n\nUltimate character arc resolution: Direction established, exact events TBD\n\nFuture Dragon evolution / awakening: Reserved for future development\n\nVisual Details\n\nExact height: Currently designed around 5''8\" / 173 cm but may be adjusted before final 3D model lock.\n\nExact braid count: Flexible\n\nExact number of beads: Flexible\n\nExact jewelry arrangement: Flexible\n\nMinor outfit ornamentation: Flexible\n\nMakeup intensity: Flexible by scene\n\nNail design: Flexible\n\nCeremonial clothing: Expandable\n\nSunken Dominion wardrobe: Expandable\n\nIgnis Peaks casual wardrobe: Expandable\n\nCombat wardrobe: Expandable\n\nPowers\n\nMaximum Steam temperature: TBD\n\nMaximum pressure output: TBD\n\nMaximum Bubble Prison size: TBD\n\nMaximum number of simultaneously controlled bubbles: TBD\n\nMaximum Dragon size: TBD\n\nExact stamina limits: TBD\n\nUltimate technique: TBD\n\nPotential awakened transformation: TBD\n\nThese should remain open until the wider power scale of Umbral Genesis is finalized.","canonLocks":"The following characteristics are locked canon for Ife and should remain consistent across writing, artwork, VRoid models, Blender models, animation, promotional material, and Umbra Connect.\n\nIdentity\n\nName: Ife\n\nPronunciation: EE-feh\n\nPrimary Title: The Pink Steam Dragon\n\nGender: Female\n\nPronouns: She / Her\n\nSpecies: Half-Primordial Dragon / Elemental Dragon\n\nElement: Steam\n\nElemental Equation:\nFire + Water → Steam\n\nParentage\n\nFather: Ignis — Primordial Fire\n\nMother: Leviathans — Primordial Water\n\nThis parentage should never change.\n\nSibling Relationships\n\nRahim — Full Brother\nIgnis + Leviathans\nBlood Dragon\nCurrently missing.\n\nRuchika — Maternal Half-Brother\nLeviathans + Terrax\nBone Dragon\nCreator of Ife''s Bone Dragon Whip.\n\nEzra — Paternal Half-Brother\nIgnis + Aetheros\nSapphire / Lightning Dragon.\n\nAshóNodia “Ash” — Paternal Half-Brother\nIgnis + Hecate\nAsh Dragon.\n\nCritical Story Lock:\nIfe currently does not know Ash exists.\n\nResidence\n\nPrimary residence:\n\nMoltenmaw Caverns — Ignis Peaks\n\nIfe primarily lives with Ignis.\n\nThe Sunna\n\nThe Sunna is one of Ife''s favorite places.\n\nShe can safely sleep beneath its molten surface.\n\nHer unconscious Steam magic causes the lava to boil and churn.\n\nHer Bubble Sorcery can encapsulate molten lava inside floating magical bubbles.\n\nHuman Appearance\n\nIfe is a dark-skinned woman of mixed African and Asian heritage.\n\nHer complexion remains deep warm reddish-mahogany brown.\n\nHer skin should never be significantly lightened between visual adaptations.\n\nPrimary Skin: #6B3B32\n\nShe has:\n\nType 4C natural hair\nExtremely long black braids\nPartially raised braided crown/bun\nPink beads and gemstones\nBronze/copper hair ornaments\nCosmic pink eyes\nAthletic, curvaceous build\nWarm metallic jewelry\nPink-centered wardrobe\nEye Design\n\nHer eyes are Cosmic Pink.\n\nThey contain:\n\nRose\nMagenta\nViolet\nPearl\nBubble-like iridescence\nStar-like highlights\n\nThey should never become ordinary flat pink eyes.\n\nPrimary Iris: #E75C9A\n\nSignature Color\n\nPink\n\nMore specifically:\n\nRose / Steam Pink / Bubble Pink\n\nPink belongs visually to Ife, not simply to Fire or Water.\n\nSignature Metals\n\nBronze\nCopper\nWarm Gold\n\nBright silver should not replace these as her dominant jewelry metals.\n\nSignature Weapon\n\nThe Bone Dragon Whip\n\nCreated by:\n\nRuchika\n\nThe weapon is:\n\nDragon-bone based\nSegmented\nFlexible\nHeat-resistant\nSteam conductive\nLiving/magical\nSelf-repairing\nSpecifically attuned to Ife\n\nThe creator should never be changed to Ignis, Leviathans, or another character.\n\nCore Magic\n\nIfe''s personal magic must remain centered around:\n\nSteam\n\nPressure\n\nCondensation\n\nBubble Sorcery\n\nShe should not gradually become a generic Fire-and-Water mage.\n\nFire and Water are her elemental ancestry.\n\nSteam is Ife''s element.\n\nAnger Tell\n\nWhen Ife becomes extremely angry or loses emotional control:\n\nSuperheated steam begins escaping from her nose and ears.\n\nThis is a signature visual character trait.\n\nTrue Form\n\nIfe''s true form is:\n\nThe Pink Steam Dragon\n\nCore visual traits include:\n\nDeep rose-pink scales\nPink/crimson scale variations\nCosmic pink eyes\nTranslucent underlayers\nIridescent bubble-film wing membranes\nObsidian-edged markings\nInternal volcanic glow\nLong tail\nElegant horns\nConstant supernatural steam\nBubble manifestations\n\nHer Dragon form should remain recognizably connected to her human palette.\n\nPersonality Core\n\nIfe is fundamentally:\n\nA Protector.\n\nShe is warm, observant, responsible, structured, reserved, dependable, and family-oriented.\n\nHer temper is powerful but normally controlled.\n\nHer protective personality should never be mistaken for passivity.\n\nCore Character Theme\n\nIfe represents:\n\nBalance between opposing forces.\n\nFire does not defeat Water.\n\nWater does not extinguish Fire.\n\nTogether they create something new.\n\nSteam.","galleryUrl":"","mediaNotes":"Primary Visual Style\n\nAnime Fantasy / High-Fantasy Character Design\n\nIfe should maintain a recognizable anime foundation while using detailed materials, realistic lighting, elaborate clothing, and high-quality fantasy rendering.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/838c6109-b23b-4fb2-aba6-af377de4497c/portrait/1790288374064-ife-character-portrait.png","visualAssets":"Official Character Portrait\nCompleted — human-form portrait establishing Ife’s face, complexion, eyes, hair, jewelry, makeup, and overall visual identity.\n\n☑ Human Form Production Sheet\nCompleted — comprehensive visual reference showing her human appearance, outfit construction, facial details, hair, accessories, palette, and other identifying features.\n\n☑ Human Form 4-View Turnaround\nCompleted — front, left side, back, and right side references intended for VRoid/Blender modeling.\n\n☑ Human Form Face Close-Up\nCompleted.\n\n☑ Eye Detail Reference\nCompleted — cosmic pink, violet, and iridescent bubble-like iris.\n\n☑ Hair Reference\nCompleted — Type 4C hair arranged into extremely long decorated braids with a partially raised braided crown/bun.\n\n☑ Makeup Reference\nCompleted — heated rose, plum, berry, and pearl-pink makeup palette.\n\n☑ Skin Color Reference\nCompleted.\n\n☑ Official HEX Palette\nCompleted.\n\n☑ Hands / Nail Reference\nCompleted.\n\n☑ Jewelry / Accessories Reference\nCompleted.\n\n☑ Signature Outfit Reference\nCompleted.\n\n☑ Outfit Breakdown\nCompleted — individual clothing components available for modeling/texturing reference.\n\n☑ Alternate Outfit Concepts\nCompleted at concept level.\n\n☑ True Dragon Form Reference\nCompleted.\n\n☑ Dragon Production Sheet\nCompleted — includes multiple angles, head details, wing membranes, scale textures, elemental effects, and size comparison.\n\n☑ Dragon Head Reference\nCompleted.\n\n☑ Dragon Eye Reference\nCompleted.\n\n☑ Dragon Wing Reference\nCompleted.\n\n☑ Dragon Scale / Material Reference\nCompleted.\n\n☑ Bone Dragon Whip Reference\nCompleted.\n\n☑ Bone Dragon Whip Detail Sheet\nCompleted — includes handle, bone segmentation, extended configuration, coiled configuration, internal construction, and self-repair visualization.\n\n☑ Elemental Magic Reference\nCompleted — Steam, Bubble Sorcery, Lava Encapsulation, Guardian Bubble, Pressure attacks, and Scalding Garden visuals established.\n\n☑ Expression Sheet\nCompleted — neutral, soft, serious, happy, angry/steam, sad, teasing, and surprised expressions represented across production references.\n\n☐ Clean Blender A-Pose reference\n☐ Clean Blender T-Pose reference\n☐ Human body reference without jewelry obscuring anatomy\n☐ Hair-only 360° modeling sheet\n☐ Face orthographic — front/profile/3⁄4\n☐ Clothing texture sheet\n☐ Jewelry texture/material sheet\n☐ Eye texture map\n☐ Makeup texture map\n☐ Skin texture reference\n☐ Steam VFX sheet\n☐ Bubble VFX sheet\n☐ Dragon orthographic turnaround\n☐ Dragon wing fully extended orthographic reference\n☐ Dragon mouth/interior reference\n☐ Dragon claw/foot reference\n☐ Bone Dragon Whip orthographic modeling sheet\n☐ Combat pose sheet\n☐ Height comparison with Ignis, Leviathans, Rahim, Ruchika, Ezra, and Ash","productionNotes":"When recreating Ife in VRoid, prioritize:\n\nFace shape\nSkin tone\nCosmic pink eyes\nMakeup\n4C-inspired braided hairstyle\nBody proportions\nSignature pink clothing\nBronze/copper accessories\n\nAvoid lightening her complexion because of VRoid''s default shading or texture presets.\n\nHer skin should remain centered around:\n\n#6B3B32\n\nwith warm reddish highlights rather than pale beige highlights.\n\nBlender\n\nUse the clean human turnaround as the primary modeling reference.\n\nModel major components separately:\n\nBody Mesh\n\nHair / Braids\n\nHair Jewelry\n\nFace Jewelry\n\nNecklaces\n\nArm Jewelry\n\nWaist Jewelry\n\nSignature Clothing\n\nSheer Fabric Panels\n\nBone Dragon Whip\n\nThis allows accessories and clothing to be toggled independently for animation and alternate outfits.\n\nMaterial Notes\nSkin\n\nWarm deep-brown material with subtle moisture/specular response.\n\nIfe should look naturally hydrated rather than artificially glossy.\n\nDuring Steam magic, skin roughness can decrease slightly to simulate condensation.\n\nHair\n\nVery dark near-black material with subtle warm-brown reflections.\n\nAvoid excessive shine.\n\nClothing\n\nMix:\n\nSilk\nSheer magical fabric\nWoven textile\nEmbroidery\nMetallic trim\nMetals\n\nBronze and copper should show visible warmth and moderate age rather than looking like perfectly polished modern jewelry.\n\nGems\n\nPink gemstones should support:\n\nTransparency\nInternal glow\nRefraction\nPink/violet highlights\nBubble Magic\n\nTransparent material with:\n\nThin-film iridescence\nPink dominance\nViolet secondary reflections\nSmall cyan/blue highlights","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/838c6109-b23b-4fb2-aba6-af377de4497c/reference/1790288270869-ife-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/838c6109-b23b-4fb2-aba6-af377de4497c/alternate/1790288278147-ife-alternate-true-form.png"},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"TBD — no exact canonical age established","era":"500–1300 AD-inspired fantasy period","name":"Ife","race":"Dragon","alias":"The Steam Dragon; Protector of the Scalding Gardens","gender":"Female","titles":"The Pink Steam Dragon, Daughter of Fire and Water, Daughter of Ignis, Daughter of Leviathans, Protector of the Scalding Gardens, The Steam-Born Guardian","subrace":"Steam Dragon / Fire-Water Primordial Hybrid","summary":"Ife, known as the Pink Steam Dragon, is the daughter of Ignis, the Primordial embodiment of Fire, and Leviathans, the Primordial embodiment of Water. Born from two naturally opposing elemental forces, Ife represents the point at which Fire and Water reach equilibrium: Steam.\n\nIn human form, Ife is a dark-skinned young woman distinguished by her cosmic pink eyes, long decorated braids, copper-and-bronze jewelry, and flowing steam-woven clothing. Her normally composed appearance reflects her reserved and dependable personality, while subtle heat, moisture, and pink steam continuously hint at the immense elemental pressure contained within her body.\n\nIfe is naturally protective, responsible, observant, and strongly attached to her family. She rarely seeks conflict for its own sake, but threatening someone under her protection can trigger an explosive change in temperament. As her anger rises, the elemental pressure within her body increases until visible superheated steam begins escaping from her nose and ears.\n\nHer magic combines superheated steam and supernatural bubble manipulation. She can produce dense steam clouds, create durable bubble barriers, imprison enemies inside pressurized bubbles, manipulate extreme heat and pressure, and encapsulate even molten lava within magically reinforced spheres.\n\nHer signature weapon is the Bone Dragon Whip, crafted for her by her maternal half-brother Ruchika, the Bone Dragon. Modeled from Ruchika''s own tail-bone structure, the weapon is flexible, heat-resistant, magically self-repairing, and specifically attuned to Ife. She can channel steam through its living bone structure, transforming an already dangerous segmented whip into a scalding extension of her elemental power.\n\nIn her true dragon form, Ife becomes an enormous deep rose-pink Steam Dragon whose body combines draconic armor with translucent, bubble-like structures. Iridescent membranes shimmer across her wings while obsidian-edged markings glow with internal volcanic heat. Superheated pink steam perpetually surrounds her body, partially obscuring her silhouette.\n\nDespite being born from forces capable of reshaping entire realms, Ife is fundamentally a guardian. Fire gave her heat. Water gave her fluidity. But the balance between them created something belonging entirely to her.\n\nSteam is her breath. Bubbles are her prison. Lava is her playground.","heritage":"Mixed African and Asian heritage.","homeland":"Ignis Peaks — born into the elemental bloodlines of Fire and Water, with ancestral ties to both the Ignis Peaks and the Sunken Dominion.","pronouns":"She / Her","birthDate":"TBD","nicknames":"Pink Steam","occupation":"Elemental Guardian / Protector / Dragon Warrior","affiliation":"Ignis Peaks — born into the elemental bloodlines of Fire and Water, with ancestral ties to both the Ignis Peaks and the Sunken Dominion.","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"“Ife” is a Yoruba name associated with love. This meaning suits her protective nature particularly well: despite possessing destructive elemental power, love for her family and those under her protection is one of her strongest motivations.","nationality":"Primordial Dragonkin of the Ignis Peaks","spoilerLevel":"Minor / Major depending on entry.","pronunciation":"EE-feh","currentResidence":"Moltenmaw Caverns, Ignis Peaks","elementalHeritage":"Fire + Water → Steam"},"abilities":{"weapons":"Primary Weapon\n\nThe Bone Dragon Whip\n\nSecondary Equipment\n\nBronze and copper jewelry\n\nPink elemental gemstones\n\nHeat-resistant clothing\n\nUtility belt\n\nProtective arm cuffs\n\nMagically reinforced accessories\n\nIfe generally carries very little conventional equipment because her elemental abilities provide most of what she requires.","strengths":"Exceptional Battlefield Control\n\nIfe can manipulate where opponents move and how safely they can approach her.\n\nDefensive Versatility\n\nShe can protect herself, individuals, or entire groups.\n\nEnvironmental Adaptability\n\nHeat, humidity, volcanic environments, and water-heavy environments generally favor her.\n\nThermal Resistance\n\nMany conventional heat-based attacks have dramatically reduced effectiveness against her.\n\nPressure Manipulation\n\nAllows tremendous force without requiring direct physical contact.\n\nWeapon Synergy\n\nThe Bone Dragon Whip functions almost like another part of her elemental body.\n\nHybrid Element\n\nSteam behaves differently from either Fire or Water alone, making her abilities difficult to counter through simplistic elemental logic.\n\nProtective Instinct\n\nIfe becomes extraordinarily focused when another person''s safety depends on her.","weaknesses":"Extreme Cold\n\nSevere cold can interfere with Ife''s ability to maintain high-temperature steam.\n\nIt does not automatically remove her powers, but forces her to expend substantially more energy maintaining temperature.\n\nExtremely Dry / Moisture-Depleted Environments\n\nIfe generates supernatural moisture internally, so she is never completely powerless in dry environments.\n\nHowever, producing massive quantities of steam without surrounding moisture requires greater personal energy.\n\nOverpressure\n\nIfe''s body functions like a supernatural pressure system.\n\nGenerating too much steam without properly venting it can become physically uncomfortable and eventually dangerous.\n\nVisible warning signs include:\n\nSteam escaping from her ears\nSteam escaping from her nose\nIncreased body temperature\nBrightening eyes\nUncontrolled condensation\nSpontaneous bubble formation\nProtective Exploitation\n\nIfe''s greatest psychological strength can also become a weakness.\n\nShe will frequently prioritize protecting another person over taking the tactically optimal action.\n\nAn intelligent enemy could attempt to exploit this.\n\nEmotional Pressure\n\nAnger increases her elemental output but decreases precision if allowed to escalate too far.\n\nMore power does not always mean better control.","combatStyle":"Defensive Zoner / Battlefield Controller / Mid-Range Whip Fighter","limitations":"Steam Requires Balance\n\nIfe''s greatest techniques require maintaining the correct relationship between heat and moisture.\n\nToo much heat without sufficient moisture produces unstable output.\n\nToo much moisture without sufficient heat reduces steam intensity.\n\nHer greatest mastery comes from maintaining equilibrium.\n\nBubble Durability Is Not Infinite\n\nHer bubbles are extraordinarily strong, but they can be broken by sufficient force.\n\nLarger bubbles require more energy to maintain.\n\nProtecting multiple people simultaneously increases that cost further.\n\nPressure Has Consequences\n\nCompressed steam stores enormous energy.\n\nIf one of Ife''s pressure bubbles is destroyed unexpectedly, the resulting release can endanger allies as well as enemies.\n\nShe must therefore remain aware of where every high-pressure construct is positioned.\n\nLarge-Scale Techniques Require Concentration\n\nTechniques such as Scalding Garden require Ife to track many independent constructs simultaneously.\n\nThe more bubbles she controls, the greater the mental load.\n\nDragon Form Increases Consumption\n\nHer Dragon form can produce dramatically greater elemental output, but sustaining maximum power consumes far more energy than fighting in human form.\n\nBone Dragon Whip Dependency\n\nIfe does not require the whip to use her magic.\n\nHowever, losing access to it removes one of the primary tools through which she controls mid-range combat.\n\nShe remains dangerous without it, but her fighting style changes considerably.","powerSource":"Primordial Elemental Bloodline","abilityNotes":"Ife''s abilities should always follow the visual language of Steam + Pressure + Bubbles.\n\nShe should not gradually become a generic Water mage who throws ordinary water attacks or a Fire mage who simply launches flames.\n\nThose elements belong to her parents.\n\nSteam belongs to Ife.\n\nEven when she uses inherited elemental principles, they should transform through her unique nature.\n\nFire becomes heat.\n\nWater becomes moisture.\n\nHeat + moisture becomes steam.\n\nSteam becomes pressure.\n\nCondensation becomes bubbles.\n\nBubbles become containment.\n\nPressure turns containment into a weapon.\n\nThat chain should remain the central logic behind her entire power system.\n\nHer magic should also reflect her personality.\n\nShe is a protector, so many abilities have both defensive and offensive applications.\n\nA bubble can shield a child.\n\nThe same bubble can imprison an enemy.\n\nSteam can hide an ally''s escape.\n\nThe same steam can become lethally hot.\n\nHer whip can pull someone away from danger.\n\nThe same whip can bind an opponent and channel scalding steam directly against them.\n\nThat duality is fundamental to Ife:\n\nShe possesses powers capable of horrific destruction, but her first instinct is usually to place those powers between danger and the people she loves.","combatProfile":"Combat Role: Defender / Controller\n\nPreferred Range: Mid-range\n\nSecondary Range: Close-range\n\nLong Range: Moderate through pressure attacks and environmental manipulation\n\nDefense: Exceptional\n\nBattlefield Control: Exceptional\n\nMobility: High\n\nPhysical Strength: High\n\nElemental Output: Extremely High\n\nWeapon Skill: Expert\n\nDurability: Very High\n\nThermal Resistance: Extraordinary\n\nPrecision: High\n\nStealth: Moderate normally / High inside steam\n\nCombat Temperament: Controlled and protective\n\nIfe is at her most dangerous when defending another person.\n\nThreatening her personally may provoke resistance.\n\nThreatening someone behind her can provoke overwhelming retaliation.","weaponDetails":"The Bone Dragon Whip\n\nCreator: Ruchika, the Bone Dragon\n\nOwner: Ife\n\nAttunement: Ife only\n\nMaterial: Living magical bone modeled from Ruchika''s tail-bone structure\n\nWeapon Type: Segmented Dragon-Bone Whip\n\nThe Bone Dragon Whip consists of numerous articulated bone segments connected through living magical tendons.\n\nEach segment moves almost like a miniature vertebra.\n\nThis gives the weapon extraordinary flexibility while preserving the structural strength of Dragon bone.\n\nHeat Resistance\n\nThe whip can withstand Ife''s extreme temperatures without weakening.\n\nSteam Conduction\n\nChannels running through the weapon allow Ife to send steam through its internal structure.\n\nSelf-Repair\n\nIf broken, fractured segments attempt to reconnect.\n\nBone fragments pull toward one another and reform through Ruchika''s lingering Bone magic.\n\nElemental Attunement\n\nThe weapon recognizes Ife''s elemental signature.\n\nIt responds most effectively to her Steam magic and resists being properly controlled by another wielder.\n\nLiving Flexibility\n\nThe whip can subtly alter the positioning of individual segments during movement.\n\nThis makes its trajectory unusually difficult for opponents to predict.","transformations":"Human Form\n\nIfe''s default form.\n\nShe retains full access to most Steam and Bubble Sorcery while maintaining human proportions.\n\nThis form provides the greatest precision.\n\nSteam Surge\n\nA heightened elemental state triggered voluntarily or through intense emotion.\n\nVisible changes include:\n\nBrighter pink eyes\nIncreased skin sheen\nIridescent markings becoming visible\nSteam continuously leaving her body\nHair ornaments vibrating from pressure\nBubbles forming spontaneously\nHeat distortion surrounding her silhouette\n\nHer Steam output and pressure manipulation increase considerably.\n\nDragon Form\n\nThe Pink Steam Dragon\n\nIfe releases her human shape and assumes her full elemental Dragon body.\n\nHer physical strength, durability, elemental capacity, flight, and area-of-effect attacks increase dramatically.\n\nPressure-Crowned Dragon State\n\nA high-output Dragon state in which Ife allows enormous quantities of steam pressure to accumulate around her body.\n\nA rotating halo or crown of bubbles and vapor forms around her head, neck, wings, and spine.\n\nHer translucent wing membranes become intensely iridescent.\n\nPink steam becomes so dense around her that portions of her Dragon body periodically disappear from sight.\n\nThis is not a separate species or transformation.\n\nIt is Ife pushing her Dragon form toward its highest sustainable elemental output.","primaryAbilities":"Superheated Steam Generation\n\nIfe can generate enormous quantities of steam directly from her body.\n\nShe can release it through:\n\nHer mouth\nHer nose\nHer hands\nHer skin\nHer Dragon form\nHer Bone Dragon Whip\n\nThe temperature ranges from harmless warm mist to devastating supernatural steam capable of causing severe thermal damage.\n\nSteam Manipulation\n\nOnce steam exists around her, Ife can manipulate its:\n\nDirection\nDensity\nTemperature\nSpeed\nShape\nConcentration\nPressure\n\nShe can create thin mist, concentrated jets, dense clouds, spiraling currents, or massive steam formations.\n\nBubble Sorcery\n\nIfe creates supernatural bubbles using condensed Water magic reinforced by thermal pressure.\n\nThese bubbles can vary from marble-sized spheres to structures large enough to contain people, creatures, attacks, or environmental material.\n\nThey can be used offensively or defensively.\n\nHer bubbles can:\n\nTrap enemies\nProtect allies\nCarry objects\nContain steam\nContain extreme heat\nStore pressure\nRedirect attacks\nFloat\nMove under Ife''s control\nEncapsulate molten lava\n\nTheir surfaces possess an iridescent pink-violet-blue sheen resembling soap-bubble film.\n\nThermal Pressure Manipulation\n\nPressure is one of Ife''s most dangerous abilities.\n\nShe can compress steam within a restricted area before releasing it violently.\n\nThis allows her to transform something visually beautiful—such as a floating pink bubble—into an extremely dangerous pressure weapon.\n\nThe more tightly she compresses steam, the greater the force generated when containment is released.\n\nExtreme Thermal Resistance\n\nIfe possesses extraordinary resistance to:\n\nFire\nLava\nBoiling water\nSteam\nExtreme humidity\nVolcanic environments\nSudden temperature increases\n\nShe can physically rest beneath molten lava without injury.\n\nThe Sunna is effectively a bath to her.\n\nSteam Respiration\n\nIfe can comfortably breathe within extremely hot, humid, steam-filled environments that would incapacitate ordinary beings.\n\nHer Dragon physiology allows her respiratory system to function under extreme temperature and pressure conditions.\n\nElemental Condensation\n\nIfe can rapidly cool portions of her own steam, turning vapor into concentrated moisture.\n\nThis allows her to recycle portions of her elemental output rather than allowing all generated vapor to dissipate.","secondaryAbilities":"Steam Veil\n\nIfe surrounds herself with steam, obscuring her body and making it difficult for opponents to determine her exact position.\n\nHeat Shimmer\n\nExtreme temperature around her body can distort light, causing her silhouette to appear unstable or blurred.\n\nBubble Platforms\n\nIfe can create reinforced floating bubbles capable of temporarily supporting herself or another person.\n\nThese allow unusual aerial movement without requiring full Dragon transformation.\n\nSteam Propulsion\n\nConcentrated steam can be released behind or beneath her body to produce sudden bursts of movement.\n\nShe can use this for:\n\nDodging\nJump enhancement\nMidair correction\nRapid acceleration\nPressure Detection\n\nBecause Ife is extraordinarily sensitive to changes in air and vapor pressure, she can detect disturbances moving through nearby steam.\n\nInside a sufficiently dense steam field, this gives her an unusual form of environmental awareness.\n\nAn enemy moving through her mist disrupts the pressure around them.\n\nIfe can feel it.\n\nCondensation Tracking\n\nIfe can leave nearly invisible traces of magical moisture on objects or individuals.\n\nWithin a limited distance, she can sense her own elemental residue.\n\nLava Encapsulation\n\nOne of Ife''s most visually recognizable abilities.\n\nShe can surround molten lava with reinforced bubble membranes.\n\nThe resulting spheres appear as translucent pink bubbles containing glowing molten rock.\n\nThey can float peacefully around her—or become extremely dangerous battlefield weapons.","signatureTechniques":"Steam Lash\n\nIfe channels superheated steam through the internal marrow channels of the Bone Dragon Whip.\n\nEvery segment becomes surrounded by pressurized vapor.\n\nWhen the whip strikes, the target receives both the physical impact of the bone weapon and a concentrated thermal burst.\n\nPressure Spike\n\nIfe creates a small reinforced bubble containing highly compressed steam.\n\nShe then collapses or punctures one side of the membrane.\n\nThe stored pressure erupts through the opening as an extremely concentrated blast.\n\nIt functions almost like a magical pressure cannon.\n\nScalding Bind\n\nIfe wraps the Bone Dragon Whip around an opponent.\n\nOnce the target is restrained, steam flows through the weapon and surrounds the bound area.\n\nThe longer the opponent remains trapped, the greater the heat and pressure become.\n\nIfe can control the temperature, allowing this technique to function as either restraint or severe punishment.\n\nSteam Whip Cyclone\n\nIfe rotates the Bone Dragon Whip around herself at high speed while releasing steam through its segments.\n\nThe motion creates a rotating vortex of whip strikes, scalding vapor, and pressure.\n\nThis technique serves simultaneously as offense and defense.\n\nApproaching her while the cyclone is active becomes extremely dangerous.\n\nBubble Prison\n\nIfe traps an opponent inside a reinforced bubble.\n\nShe can then manipulate conditions within it.\n\nPossible effects include:\n\nIncreasing temperature\nFilling it with steam\nIncreasing internal pressure\nRestricting oxygen\nSuspending the target above the ground\nTransporting the prisoner\n\nIfe usually uses the technique for containment rather than execution.\n\nGuardian Bubble\n\nA large defensive bubble forms around an ally or group.\n\nUnlike Bubble Prison, the internal environment remains safe and breathable.\n\nThe membrane absorbs and redistributes incoming force.\n\nPinkout\n\nIfe rapidly floods an area with extremely dense pink steam.\n\nVisibility collapses almost completely.\n\nBecause Ife can detect pressure disturbances inside her own steam, she retains a major sensory advantage while opponents become disoriented.\n\nScalding Garden\n\nOne of Ife''s major battlefield-control techniques.\n\nIfe fills an area with dozens or hundreds of floating bubbles of different sizes.\n\nSome contain:\n\nSteam\nCompressed pressure\nCondensed water\nEmpty space\nMolten material\n\nAn opponent cannot easily determine which bubbles are harmless and which are dangerous.\n\nIfe moves through this field while manipulating the bubbles around allies and enemies.\n\nThe battlefield becomes her Scalding Garden.\n\nThis technique is the origin of the title:\n\nProtector of the Scalding Gardens.\n\nLava Bloom\n\nIfe encapsulates portions of molten lava inside multiple reinforced bubbles.\n\nThe glowing spheres rise around the battlefield like flowers opening around her.\n\nShe can launch them individually, use them as barriers, or deliberately rupture their membranes.\n\nDragon''s Breath — Scalding Veil\n\nIn Dragon form, Ife exhales an enormous torrent of superheated pink steam.\n\nUnlike conventional Dragon fire breath, the attack expands rapidly after release.\n\nThis allows it to engulf a much wider area.","transformationDetails":"Human → Dragon\n\nSteam begins pouring from Ife''s body.\n\nHer surroundings become increasingly obscured until her human silhouette is almost impossible to see.\n\nWithin the steam, her body expands.\n\nPink scales emerge first across her shoulders, spine, arms, and face.\n\nHer skeletal structure lengthens.\n\nHer fingers develop into claws.\n\nHer spine extends into a tail.\n\nHer wings unfold last.\n\nWhen they open, the surrounding steam is violently pushed outward.\n\nThe completed transformation reveals the Pink Steam Dragon within the dissipating cloud."},"is_public":true,"appearance":{"build":"Athletic, curvaceous, feminine build, Defined but feminine shoulders, Strong arms, Narrow-to-moderate waist, Full hips, Powerful thighs, Strong calves, Balanced hourglass proportions","nails":"Medium-to-long almond-shaped nails.\n\nBase: translucent dusty rose.\n\nPrimary Nail Pink: #C77B91\nDeep Rose Accent: #87485F\nPearl Highlight: #F2CAD5\n\nSome nails may feature extremely fine bronze detailing or tiny bubble motifs.\n\nThey should remain elegant enough for her visual design while still being practical enough to control her weapon.","eyeHex":"Main Iris Pink: #E75C9A Deep Iris: #8E285E Light Iris Pink: #FF8FC5 Galaxy Violet: #9C68D7 Magical Glow: #FFD0EA Outer Iris Ring: #6F204E Hot-Pink Ring: #FF72B6 Pupil: #291224","height":"5''8\" / approximately 173 cm","makeup":"Ife uses a heated rose and wet-iridescent makeup palette.\n\nBlush: Burnt Rose #9E5360\nBlush Highlight: #BC6E78\nContour: #4D2928\n\nUpper Eyeshadow: Deep Plum #6E294E\nMain Eyeshadow: Rose Mauve #A94D72\nInner Lid: Iridescent Pink #E989B6\nEye Highlight: Pearl Pink #FFD0E5\n\nEyeliner: Black-Plum #25151F\nLower Lash Shadow: Smoky Burgundy #713146\n\nLip Liner: Deep Berry-Brown #642D3D\nLip Base: Burnt Rose #9E4E60\nLip Center: Pink Rose #C96A82\nLip Highlight: Bubble Pearl #EDADC5\n\nHer eyeliner extends slightly beyond the outer corners of her eyes, subtly mimicking the sharp shape of a dragon’s eye.\n\nDuring elemental activity, an extremely faint iridescent pink shimmer may appear beneath her eyes and across her upper cheekbones.","weight":"TBD","hairHex":"Primary Hair: #171116 Warm Black: #24191D Brown Highlight: #49302F Pink Magical Reflection: #8B405F","skinHex":"Primary Skin: #6B3B32 Warm Midtone: #805044 Warm Highlight: #A96E5D Bright Highlight: #C58B78 Shadow: #45241F Deep Shadow: #2A1615","eyeColor":"Cosmic Pink / Iridescent Pink-Violet","grooming":"Meticulous but not excessively polished.\n\nIfe takes particularly good care of her hair, skin, jewelry, and clothing. Her accessories are maintained carefully because several carry familial or elemental significance.\n\nHer skin naturally maintains a moisturized appearance due to her Water/Steam physiology.","skinTone":"Deep, rich warm brown complexion with strong reddish-mahogany undertones.","wardrobe":"Ife owns several clothing categories beyond her signature outfit.\n\nIgnis Peaks Casual Wear\nA simplified wrapped top with loose trousers or a shorter layered skirt. Less jewelry and fewer flowing panels. Used while relaxing around Moltenmaw Caverns.\n\nSunna / Lava-Resting Attire\nExtremely minimal heatproof garments designed for resting within or around the Sunna. Most conventional clothing would be unnecessary while submerged in molten environments.\n\nCombat Attire\nA tighter, more secured version of her signature outfit. Flowing sections are shortened or magically controlled to prevent interference with the Bone Dragon Whip.\n\nCeremonial Attire\nLonger and significantly more elaborate. Features extensive bronze jewelry, pink gemstones, translucent bubble-film fabrics, and visual symbolism representing both Fire and Water.\n\nSunken Dominion Attire\nClothing influenced more heavily by her maternal heritage and Leviathans’ aquatic realm, emphasizing flowing silhouettes, iridescent materials, pearls, water motifs, and cooler pink-violet accents.","hairColor":"Natural Black","hairStyle":"Long, intricate braids arranged into a partially raised braided crown/bun with the remaining braids falling down her back.  The braids reach approximately to her lower back or upper thighs and are decorated selectively with:  Pink glass/crystal beads Bronze rings Copper cuffs Small bubble-shaped ornaments Fine metallic chains  Several thinner face-framing braids remain loose around her temples and cheeks.  The hairstyle should feel elaborate without becoming perfectly symmetrical.","accessories":"Ife wears numerous carefully selected metallic and gemstone accessories:\n\nLarge bronze/gold hoop earrings\nPink gemstone earrings\nForehead jewelry\nFine head chains\nBraided hair rings\nPink hair beads\nBronze braid cuffs\nLayered necklaces\nChoker\nUpper-arm cuffs\nBracelets\nWrist cuffs\nWaist chains\nDecorative belt\nHip chains\nAnklets\nPink bubble-shaped gemstones\n\nMost jewelry uses bronze, copper, and warm gold rather than bright yellow gold.\n\nCircular designs symbolize bubbles, water droplets, pressure chambers, and the union of Fire and Water.","faceDetails":"Ife has a softly angular oval face with:\n\nHigh cheekbones\nDefined jawline\nFull lips\nStraight-to-softly broad nose\nAlmond-shaped eyes\nThick natural eyebrows\nLong dark eyelashes\nSlightly upturned outer eye corners\n\nHer resting expression is usually calm, observant, and somewhat reserved.\n\nHer eyes carry most of her emotional expression.\n\nWhen angry, her expression changes dramatically: brows lower, pupils intensify, jaw tightens, and steam begins escaping around her face.","hairTexture":"Type 4C","colorPalette":"Deep Mahogany — #6B3B32\nWarm Brown — #805044\nSkin Highlight — #A96E5D\n\nHair\nDragon Black — #171116\nWarm Black — #24191D\n\nSignature Pink\nSteam Rose — #C77B91\n\nMagic Pink\nCosmic Pink — #E75C9A\n\nLight Pink\nBubble Blush — #E5A7B8\n\nPearl Pink\nSteam Pearl — #F2CAD5\n\nDeep Rose\nPressure Rose — #87485F\n\nViolet\nBubble Violet — #9C68D7\n\nIridescent Blue Accent\nBubble Blue — #82C9DF\n\nBronze\nDragon Bronze — #9B633B\n\nCopper\nMolten Copper — #B96E46\n\nGold\nSteam Gold — #D9A568\n\nObsidian\nVolcanic Black — #21191C\n\nHer dominant visual hierarchy should be:\n\nDeep Brown + Pink + Bronze\n\nwith\n\nViolet + Iridescent Blue + Gold","dominantHand":"Dominant Hand Right-handed","outfitColors":"Main Fabric\nDusty Steam Pink — #C77B91\n\nSecondary Fabric\nLight Rose — #E5A7B8\n\nTranslucent Fabric\nPearl Pink — #F2CAD5\n\nFabric Shadows\nDeep Rose — #87485F\n\nLight Neutral Accent\nWarm Cream — #E8D3C0\n\nBronze Hardware\n#9B633B\n\nCopper Hardware\n#B96E46\n\nGold Highlights\n#D9A568\n\nPink Gemstones\n#D9568D\n\nGemstone Highlights\n#FFB4DB\n\nIridescent Reflection\n#B894E8 / #82C9DF","alternateForm":"Pink Steam Dragon\n\nIfe’s true form is an enormous serpentine-winged dragon covered primarily in deep rose-pink scales.\n\nHer dragon body features:\n\nDeep rose and crimson-pink armored scales\nTranslucent scale underlayers\nObsidian-edged markings\nInternal orange-red volcanic glow\nIridescent bubble-film wing membranes\nLong flexible tail\nElegant elongated horns\nSharp swept-back facial spines\nCosmic pink eyes\nConstant supernatural steam aura\n\nHer wing membranes are particularly distinctive. Rather than appearing completely opaque, they resemble extremely durable soap-bubble film, producing pink, violet, blue, and pearlescent reflections as light passes across them.","clothingStyle":"Early-medieval fantasy clothing influenced by African/Sahelian silhouettes combined with supernatural Steam Dragon materials.\n\nIfe favors flowing garments that allow unrestricted movement. Her clothing balances elegance with practicality rather than functioning as heavy armor.\n\nHer signature aesthetic combines:\nDraped fabric\nLayered skirts\nSplit panels\nWrapped fabric\nDecorative belts\nMetallic body jewelry\nArm cuffs\nLight protective pieces\nSemi-translucent magical textiles\n\nHer clothing frequently incorporates bubble and circular motifs.","appearanceNotes":"Ife should always visually communicate the meeting point between Fire and Water.\n\nNothing about her design should make her appear exclusively fire-aligned or exclusively water-aligned.\n\nHer warm skin, bronze metals, volcanic highlights, and occasional orange-red glow represent Ignis and Fire.\n\nHer flowing fabrics, iridescence, bubble motifs, translucent materials, moisture, and fluid movement represent Leviathans and Water.\n\nPink belongs specifically to Ife.\n\nIt is the visual bridge between those inherited forces and should remain her dominant supernatural color.\n\nEven when completely still, Ife should look subtly unusual. Light may catch moisture on her skin. A braid ornament may appear slightly fogged. A tiny bubble may briefly form and disappear near her hand. Heat may distort the air immediately around her.\n\nThese effects should remain understated while she is calm.\n\nWhen her emotions or power increase, the same details escalate dramatically—pink steam thickens around her body, her cosmic eyes brighten, bubbles manifest in the surrounding air, her skin develops stronger iridescent highlights, and extreme heat begins distorting her silhouette.\n\nHer human form should always retain the impression that an enormous elemental dragon is being contained inside a deceptively calm body.","outfitMaterials":"Ife’s clothing is primarily made from steam-woven alchemical silk, a magically engineered lightweight textile capable of surviving the extreme conditions of the Ignis Peaks.\n\nThe material is:\n\nFire-resistant\nHeat-resistant\nMoisture-resistant\nLightweight\nHighly flexible\nBreathable\nSlightly reflective\nCapable of interacting with Ife’s steam magic\n\nSome outer panels contain translucent magical fibers that resemble wet silk or extremely thin bubble film.\n\nMetallic components are primarily bronze and copper treated to survive volcanic temperatures.\n\nPink gemstones incorporated into the outfit help conduct and stabilize portions of her elemental energy.","postureMovement":"Ife naturally stands upright with relaxed shoulders and a composed posture.\n\nHer normal movements are smooth, economical, and deliberate. She rarely wastes energy through unnecessary gestures.\n\nIn combat, however, her movement becomes much more circular and flowing. She rotates through her hips and shoulders to control the Bone Dragon Whip, allowing its segmented structure to orbit around her body before striking.\n\nHer fighting silhouette should therefore resemble a mixture of:\n\nflowing water + rising steam + the snapping violence of a whip.","signatureOutfit":"Ife’s signature outfit consists of a fitted, wrapped upper garment combined with flowing asymmetrical skirt panels and semi-transparent steam-woven fabric.\n\nThe upper garment crosses around the chest and torso while leaving enough freedom for her shoulders and arms to control her whip.\n\nA decorated metallic belt anchors several layered pieces of fabric around her hips.\n\nLong translucent pink panels descend from her waist and move dramatically whenever she walks, fights, or releases steam.\n\nBronze arm cuffs, bracelets, waist jewelry, anklets, and gemstone ornaments complete the outfit.\n\nThe overall appearance should communicate:\n\nSteam Dragon Princess + Warrior + Guardian\n\nwithout relying on conventional plate armor.","distinguishingFeatures":"Ife can immediately be recognized by several traits:\n\nCosmic pink irises with bubble-like iridescence.\n\nDeep warm-brown skin.\n\nExtremely long decorated black braids.\n\nPink, bronze, copper, and gold visual palette.\n\nPersistent subtle moisture/heat shimmer around her skin.\n\nPink steam manifesting around her body when using magic.\n\nSteam escaping from her nose and ears when severely angry.\n\nBubble-like magical particles forming around her during heightened elemental activity.\n\nHer Bone Dragon Whip.\n\nIn certain lighting, extremely faint pink iridescent patterns can become visible beneath portions of her skin, resembling branching steam-pressure channels. These become more noticeable when she channels large amounts of elemental power."},"created_at":"2026-09-24T05:50:30.442929+00:00","updated_at":"2026-09-25T08:18:36.250156+00:00","is_complete":true,"origin_lore":{"fears":"Ife''s deepest fear is:\n\nBeing unable to protect someone she loves.\n\nRahim''s disappearance directly challenges her identity as a protector.\n\nShe also struggles with over-responsibility.\n\nIfe can convince herself that because she could have helped someone, she therefore should have prevented whatever happened to them.\n\nThis creates a dangerous internal question:\n\nWhere does responsibility end?\n\nShe cannot protect everyone.\n\nAccepting that is much harder for her than fighting a Dragon.\n\nAnother internal conflict comes from anger.\n\nIfe is normally controlled, but once her emotions breach that control, the immense pressure contained within her becomes physically dangerous.\n\nPart of her emotional discipline therefore comes from necessity.","goals":"Protect Her Family\n\nHer most consistent personal goal.\n\nMaster Her Element\n\nIfe wants complete command over temperature, steam density, bubble durability, and pressure.\n\nUnderstand Her Place Between Two Realms\n\nShe belongs to both Ignis and Leviathans'' elemental worlds while possessing an element belonging entirely to herself.\n\nFind Answers About Rahim\n\nHer brother''s disappearance remains unresolved.\n\nWhether she admits it openly or not, she wants to know what happened to him.\n\nBecome Strong Enough That Protection Is a Choice\n\nIfe does not want to protect others because she fears everything around them.\n\nShe wants enough strength that she can choose peace without being helpless.","beliefs":"Ife believes:\n\nStrength exists to protect something.\n\nPower without purpose means very little to her.\n\nShe respects warriors and powerful beings but is less impressed by strength used purely for intimidation.\n\nShe also believes opposing forces do not automatically need to destroy one another.\n\nHer own existence proves otherwise.\n\nFire and Water created her.\n\nContradiction created balance.\n\nThat principle influences how she views people as well as elements.","culture":"Ife possesses a mixed African and Asian heritage, inherited through her paternal and maternal bloodlines.\n\nHer upbringing is heavily influenced by the culture of the Ignis Peaks, where strength, endurance, competition, and direct displays of elemental power are commonplace.\n\nIgnis''s philosophy particularly shaped her understanding of strength.\n\nWithin his family, combat is not automatically associated with hatred.\n\nCompetition can be affection.\n\nSparring can be bonding.\n\nBeing challenged can be a sign of respect.\n\nHowever, Ife''s maternal connection to Leviathans introduced another philosophy:\n\nAdaptation.\n\nWater survives because it changes.\n\nFire survives because it consumes.\n\nSteam survives because it can do both.\n\nIfe''s worldview developed between those philosophies.","lineage":"Primordial Elemental Lineage  Paternal Element: Fire  Maternal Element: Water  Personal Element: Steam  Ife represents a successful equilibrium between opposing Primordial forces.  Her existence demonstrates that Primordial elements do not necessarily produce a simple mixture when combined through descendants.  Instead, their children can develop entirely new elemental expressions.  For Ife:  Fire + Water → Steam  Steam therefore belongs specifically to her elemental identity.  She did not inherit half of Ignis''s fire abilities and half of Leviathans'' water abilities.  Their elemental principles fused and became something new.","storyArc":"Ife''s overarching character arc centers on the difference between:\n\nProtecting someone\n\nand\n\nbelieving you are responsible for everything that happens to them.\n\nAt the beginning of her deeper story, Ife defines much of her value through usefulness.\n\nShe protects.\n\nShe stabilizes.\n\nShe fixes.\n\nShe contains.\n\nShe endures.\n\nRahim''s disappearance creates something she cannot simply fix.\n\nThat forces her to confront the limits of protection.\n\nHer eventual discovery of Ash can deepen this conflict dramatically.\n\nLearning that she had a younger brother living through danger and isolation without her knowledge could immediately trigger Ife''s instinct to compensate:\n\nI should have been there.\n\nBut she couldn''t have been.\n\nShe didn''t know.\n\nThat distinction matters.\n\nHer growth therefore does not require Ife to stop being protective.\n\nProtection is one of her greatest qualities.\n\nInstead, she must learn that:\n\nLove does not require absolute control over another person''s fate.\n\nBy the later stages of her arc, Ife can remain the fierce guardian she has always been while finally allowing her siblings, allies, and family to protect her as well.\n\nShe stops seeing herself merely as the barrier standing between her loved ones and the world.\n\nShe becomes part of the family standing together behind that barrier.\n\nAnd that development perfectly reflects her element.\n\nSteam cannot exist through Fire alone.\n\nIt cannot exist through Water alone.\n\nIfe has always been strongest when opposing forces are allowed to support one another.","backstory":"Ife was born from a contradiction.\n\nIgnis was Fire.\n\nLeviathans was Water.\n\nNeither merely controlled their respective elements. They were primordial embodiments of them.\n\nBy ordinary elemental logic, their powers should have opposed one another endlessly.\n\nTheir daughter proved otherwise.\n\nThe infant born from their union did not emerge divided between Fire and Water.\n\nShe produced steam.\n\nFrom her earliest years, Ife existed comfortably within environments that should have belonged exclusively to one parent or the other. Heat could not consume her. Moisture could not extinguish her elemental core.\n\nHer body transformed conflict into equilibrium.\n\nShe spent much of her upbringing in the Ignis Peaks under the influence of her father. Ignis valued strength, competition, courage, and the thrill of testing oneself against powerful opponents.\n\nHis children were not protected from those expectations.\n\nThey participated in them.\n\nIfe learned to fight because her father expected his children to understand their own strength.\n\nBut she never developed Ignis''s fascination with combat for combat''s sake.\n\nShe became a defender.\n\nWhere another fighter might see an enemy and think about destroying them, Ife naturally considers what stands behind her.\n\nA sibling.\n\nA friend.\n\nA home.\n\nSomeone weaker.\n\nSomething worth preserving.\n\nThat instinct eventually shaped her unusual fighting style.\n\nSteam allowed her to obscure.\n\nBubbles allowed her to contain.\n\nPressure allowed her to immobilize.\n\nHeat ensured that containment could become devastating whenever necessary.\n\nThen Ruchika gave her the weapon that completed the style.\n\nThe Bone Dragon Whip gave Ife reach.\n\nShe could surround enemies rather than charging directly toward them. She could pull threats away from allies, bind opponents, create defensive circles, and channel superheated steam directly through the weapon.\n\nHer powers and personality became reflections of one another.\n\nContain first. Protect first. Destroy only when necessary.\n\nYet Ife''s dedication to family also created her greatest vulnerability.\n\nRahim disappeared.\n\nThere was no enemy for her to bind.\n\nNo attack she could block.\n\nNo battlefield where she could simply stand between her brother and danger.\n\nFor someone whose identity revolves around protecting others, losing someone she loves without being able to stop it is profoundly difficult.\n\nAnd somewhere beyond her awareness exists another complication.\n\nAshóNodia.\n\nAnother son of Ignis.\n\nAnother Dragon.\n\nAnother brother.\n\nIfe does not know him.\n\nNot yet.","childhood":"Ife''s childhood was anything but physically ordinary.\n\nShe grew up in Moltenmaw Caverns, surrounded by volcanic chambers, magma rivers, extreme heat, Dragonkin, and beings capable of surviving conditions lethal to ordinary mortals.\n\nTo Ife, lava was never frightening.\n\nIt was home.\n\nOne of the places she became most attached to was the Sunna, the enormous lava pool used by Ignis for relaxation.\n\nIfe discovered very young that she could descend beneath its molten surface without injury.\n\nEventually, she began sleeping there.\n\nHer unconscious elemental reactions transformed the Sunna whenever she rested.\n\nSteam caused sections of the lava to bubble and churn.\n\nHer bubble magic would spontaneously surround pieces of molten rock, creating floating translucent spheres containing glowing lava.\n\nWhat would be a horrifying volcanic phenomenon to an ordinary person became one of Ife''s most peaceful childhood environments.\n\nLearning Control\n\nHer greatest childhood difficulty was not producing steam.\n\nIt was containing pressure.\n\nStrong emotions caused her internal temperature and elemental pressure to rise.\n\nAnger was particularly problematic.\n\nBefore Ife learned emotional control, irritated outbursts could fill rooms with steam, obscure entire chambers, or cause bubbles to manifest uncontrollably.\n\nEventually her family learned one particularly obvious warning sign:\n\nWhen steam begins pouring from Ife''s ears and nose, someone has pushed her considerably beyond her normal patience.","lifestyle":"Despite her extraordinary heritage, Ife enjoys surprisingly peaceful routines.\n\nShe spends considerable time within the Moltenmaw Caverns.\n\nThe Sunna is one of her favorite places.\n\nShe may disappear beneath the lava for hours simply to sleep.\n\nHer ambient magic turns the pool into something resembling an enormous volcanic jacuzzi.\n\nFloating bubbles containing molten lava often surround her.\n\nShe also:\n\nMaintains her extremely long braids.\n\nCleans and inspects the Bone Dragon Whip.\n\nOrganizes her jewelry.\n\nPractices controlled steam manipulation.\n\nCreates bubbles absentmindedly.\n\nTrains with family.\n\nVisits areas connected to her mother''s domain.\n\nEnjoys periods of solitude after spending extensive time around louder personalities.\n\nShe is one of those people who genuinely appreciates having a routine.","storyRole":"Elemental Guardian / Dragon Heir / Family Anchor\n\nIfe occupies an important position within the Primordial family because she connects several major elemental bloodlines.\n\nThrough Ignis, she is connected to Fire.\n\nThrough Leviathans, she is connected to Water.\n\nThrough Rahim, she is connected to the mystery surrounding the missing Blood Dragon.\n\nThrough Ruchika, she is connected to Terrax''s branch of the family.\n\nThrough Ezra, she is connected to Aetheros'' branch.\n\nAnd through Ash—without knowing it yet—she is connected to one of the family''s most significant hidden bloodlines.\n\nThis places Ife naturally near the center of several family conflicts even though she is not someone who actively seeks political or personal power.","birthplace":"Moltenmaw Caverns, Ignis Peaks   Ife was born within the domain of her father, Ignis, the Primordial embodiment of Fire.  Her birth was extraordinary because she was conceived from two Primordials whose natural elements fundamentally oppose one another: Fire and Water. Rather than one element destroying or suppressing the other, the two reached equilibrium within Ife.  That equilibrium became Steam.  Although the Ignis Peaks are considered her birthplace and primary homeland, Ife possesses an equally legitimate ancestral connection to her mother''s domain, the Sunken Dominion, which encompasses the waters of the world.  She therefore belongs naturally to two elemental realms without being completely defined by either.","psychology":"Ife''s psychological center is built around stability.\n\nShe is the equilibrium between two enormous opposing forces, and she subconsciously recreates that role in her relationships.\n\nShe becomes the person who stabilizes situations.\n\nThe mediator.\n\nThe protector.\n\nThe one who remembers practical things while everyone else is reacting emotionally.\n\nBut that creates a hidden weakness.\n\nPeople who constantly function as another person''s stability can begin believing they are not allowed to become unstable themselves.\n\nIfe has difficulty admitting when she needs protection.\n\nShe can offer support much more easily than she can request it.\n\nHer long-term emotional development should challenge that belief.\n\nBeing protected does not make the protector weak.","motivations":"Ife''s strongest motivation is protection.\n\nShe wants the people she loves to remain safe, even when those people are perfectly capable of defending themselves.\n\nFamily is particularly important to her.\n\nShe also seeks balance.\n\nAs the living intersection between two opposing Primordial forces, she instinctively dislikes situations where one extreme completely overwhelms another.","personality":"Primary Archetype: The Defender\n\nIfe is:\n\nWarm\nReserved\nObservant\nProtective\nDependable\nPatient\nPractical\nFamily-oriented\nResponsible\nQuietly affectionate\nExtremely stubborn when protecting someone\n\nShe rarely needs to dominate a conversation.\n\nInstead, she watches.\n\nShe notices who has eaten.\n\nWho is injured.\n\nWho has become unusually quiet.\n\nWho disappeared from the room.\n\nWho is pretending that something doesn''t hurt.\n\nHer affection frequently manifests through actions rather than speeches.\n\nHowever, her patience has limits.\n\nOnce those limits are crossed, Ife possesses an unexpectedly explosive temper.\n\nHer family knows the rule:\n\nIf steam starts coming out of her ears, stop talking.","voiceSpeech":"Ife speaks in a warm, controlled, medium-low feminine voice.\n\nHer normal speech is measured and direct.\n\nShe does not ramble unnecessarily and rarely raises her voice to establish authority.\n\nHer humor tends to be dry and understated.\n\nAround family, her voice becomes noticeably warmer and occasionally teasing.\n\nWhen irritated, her sentences become shorter.\n\nWhen genuinely angry, the opposite of what people might expect happens:\n\nIfe becomes quieter.\n\nHer voice lowers.\n\nHer words become extremely deliberate.\n\nThen the steam starts.\n\nShe does not need to scream for people to realize they are in danger.","likesDislikes":"Likes\nThe Sunna\nExtreme warmth\nHot springs\nSteam\nRain hitting warm stone\nQuiet mornings\nFamily gatherings\nOrder and routine\nBeautiful jewelry\nBronze and copper craftsmanship\nPink gemstones\nBraiding and hair decoration\nBubbles\nSwimming\nSleeping somewhere ridiculously hot\nTraining with people she trusts\nTaking care of others\nPeace after conflict\n\nDislikes\n\nNeedless cruelty\nThreats toward her family\nBetrayal\nRecklessness that endangers other people\nBeing unable to help\nUnnecessary chaos\nPeople touching her belongings without permission\nSomeone mishandling the Bone Dragon Whip\nBeing pressured to discuss emotions before she is ready\nWatching powerful people bully weaker ones\n\nPreferences\n\nFavorite Color: Pink — particularly deep rose and iridescent pink.\n\nPreferred Metals: Bronze and copper.\n\nPreferred Environment: Warm, humid, volcanic environments.\n\nPreferred Combat Distance: Mid-range transitioning into close-range.\n\nPreferred Weapon: Bone Dragon Whip.\n\nPreferred Resting Place: Beneath the Sunna.","majorLifeEvents":"Birth of the Pink Steam Dragon\n\nThe union of Fire and Water produces a new elemental Dragon lineage: Steam.\n\nChildhood in Moltenmaw\n\nIfe grows up within the volcanic environment of the Ignis Peaks and develops extraordinary thermal resistance.\n\nDiscovery of the Sunna\n\nShe begins using Ignis''s enormous lava pool as a personal resting place and eventually develops her famous habit of sleeping beneath its surface.\n\nMastery of Bubble Sorcery\n\nIfe discovers that her steam can interact with magically reinforced bubbles, allowing her to manipulate pressure, heat, containment, and protection.\n\nTraining Under Ignis\n\nIfe participates in Ignis''s brutal family sparring traditions and learns that being defensive does not mean being physically weak.\n\nThe Bone Dragon Whip\n\nRuchika crafts a living, self-repairing bone whip specifically for his sister.\n\nIt becomes Ife''s signature weapon.\n\nRahim''s Disappearance\n\nHer full brother disappears under mysterious circumstances.\n\nHis absence leaves an unresolved fracture within Ife''s otherwise family-centered worldview.\n\nThe Unknown Brother\n\nAsh exists somewhere beyond Ife''s knowledge.\n\nShe has yet to discover that Ignis has another son—or that the mysterious Ash Dragon is her younger brother."},"canon_status":"concept","current_step":6,"portrait_url":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/838c6109-b23b-4fb2-aba6-af377de4497c/portrait/1790288374064-ife-character-portrait.png","relationships":{"allies":"Her Siblings\n\nDespite their disagreements and complicated family history, Ife''s siblings represent some of her strongest natural allies.\n\nIgnis Peaks\n\nIfe has strong connections among the Dragonkin, elemental inhabitants, and loyal followers living within her father''s realm.\n\nBecause she resides there, many inhabitants recognize her not merely as Ignis''s daughter but as one of the realm''s active protectors.\n\nSunken Dominion\n\nThrough Leviathans, Ife also possesses familial and elemental ties to the inhabitants of the world''s aquatic territories.\n\nShe therefore occupies an unusual position:\n\nShe can walk comfortably among beings associated with both Fire and Water despite those elements normally existing in opposition.\n\nNamed Personal Friends\n\nTBD\n\nSpecific non-family friendships have not yet been established in canon.","rivals":"Ezra — Friendly / Sibling Rival\n\nEzra is currently Ife''s clearest natural rival.\n\nTheir rivalry centers on:\n\nSpeed versus control.\n\nLightning versus Steam.\n\nFlashiness versus patience.\n\nAggression versus containment.\n\nNeither needs to genuinely dislike the other for their battles to become intense.\n\nBeing children of Ignis also means neither expects their sibling to treat them delicately during training.\n\nAdditional Rivals\n\nTBD\n\nNo major hostile rival has yet been permanently established.","enemies":"No specific personal arch-enemy currently established.\n\nIfe naturally opposes individuals or factions threatening:\n\nHer family\nIgnis Peaks\nThe Sunken Dominion\nInnocent people under her protection\nHer siblings\nThose incapable of defending themselves\n\nHowever, these should not automatically be classified as personal enemies.\n\nA true Ife antagonist should ideally challenge her philosophy of protection, not simply be another powerful fighter.\n\nNamed Enemies: TBD","mentors":"Ignis — Combat Influence\n\nIgnis serves as one of Ife''s most important combat influences.\n\nHis family tournaments and relentless sparring taught her:\n\nDurability\nCourage\nPressure tolerance\nReading powerful opponents\nFighting while exhausted\nRefusing to panic against overwhelming strength\n\nHe did not necessarily teach Ife every technique she knows.\n\nRather, he created the environment in which weakness had to become competence.\n\nLeviathans — Elemental Influence\n\nLeviathans represents the other half of Ife''s elemental education.\n\nHer maternal influence taught Ife principles associated with:\n\nFlow\nAdaptability\nFluid movement\nPatience\nEnvironmental awareness\nChanging form rather than resisting everything directly\n\nIfe''s fighting philosophy ultimately combines lessons from both parents.\n\nRuchika — Weapon Influence\n\nRuchika''s contribution is primarily tied to Ife''s Bone Dragon Whip.\n\nHis understanding of Bone magic and the construction of her weapon allowed Ife to develop an entirely new style around Steam conduction and segmented-whip combat.\n\nStudents\n\nNone currently established.\n\nIfe does not currently have a canonical apprentice or student.\n\nThis remains available for future development.","parents":"Ignis — Father\n\nRelationship: Biological Father\nElement: Primordial Fire\nStatus: Active relationship\nRealm: Ignis Peaks\n\nIgnis is Ife''s father and one of the strongest influences on her upbringing.\n\nIfe primarily lives within Moltenmaw Caverns in the Ignis Peaks, placing her physically closer to Ignis throughout much of her everyday life.\n\nTheir personalities are very different.\n\nIgnis is fascinated by strength, competition, powerful opponents, and the thrill of testing himself against beings capable of challenging him.\n\nIfe is much more defensive and reserved.\n\nShe does not seek battle simply because someone strong exists.\n\nNevertheless, she understands her father''s philosophy better than outsiders might expect.\n\nIgnis''s brutal family sparring sessions taught Ife how to remain composed while facing opponents considerably stronger than herself. He does not dramatically hold back simply because his children are fighting him.\n\nFor Ignis, challenging his children is part of loving them.\n\nIfe grew up understanding that.\n\nShe may complain about her father''s ridiculous enthusiasm for another family tournament, but she will still participate.\n\nThe Sunna, Ignis''s enormous lava pool, has also become one of Ife''s favorite resting places. She regularly sleeps beneath its molten surface, occasionally turning her father''s peaceful lava bath into a bubbling volcanic jacuzzi through her unconscious Steam magic.\n\nTheir relationship can be summarized as:\n\nFire taught Steam how to withstand pressure.\n\nLeviathans — Mother\n\nRelationship: Biological Mother\nElement: Primordial Water\nStatus: Active relationship\nRealm: Sunken Dominion / The Waters of the World\n\nLeviathans is Ife''s mother and the source of the Water half of her elemental existence.\n\nAlthough Ife primarily resides with Ignis, she maintains a legitimate familial and elemental connection to her mother''s realm.\n\nWhere Ignis influenced Ife''s understanding of strength, Leviathans influenced her understanding of adaptation.\n\nWater does not always confront an obstacle directly.\n\nIt flows around it.\n\nWaits.\n\nChanges shape.\n\nFinds another path.\n\nThat philosophy naturally complements Ife''s personality far more closely than Ignis''s love of direct confrontation.\n\nIfe''s fluid movements, patience, defensive instincts, and adaptability all reflect aspects of her maternal heritage.\n\nHer relationship with Leviathans also prevents Ife from viewing herself solely as a daughter of the Ignis Peaks.\n\nShe belongs to Fire.\n\nShe belongs to Water.\n\nAnd ultimately, she belongs to neither completely.\n\nShe is Steam.","partner":"None currently established.\n\nIfe does not currently have a canonical romantic partner or love interest.\n\nThis portion of her character remains open rather than assigning her a relationship simply to fill the category.\n\nStatus: TBD.","children":"None currently established.\n\nIfe has no canonical children or descendants at this point in the story.\n\nStatus: TBD / Open for future story development.","siblings":"Rahim — Full Brother\n\nRelationship: Full biological brother\nShared Parents: Ignis + Leviathans\nDragon Element: Blood\nTitle: The Blood Dragon\nStatus: Missing\n\nRahim is one of the most emotionally important relationships in Ife''s life.\n\nThey share both parents, making him her full sibling within a family otherwise composed largely of half-sibling elemental branches.\n\nTheir personalities differ dramatically.\n\nRahim''s Blood Dragon nature is chaotic, aggressive, and dangerous.\n\nIfe is structured, protective, and controlled.\n\nWhere Rahim can become consumed by bloodlust, Ife naturally attempts to contain dangerous situations.\n\nThis does not make them opposites who hate one another.\n\nThey are siblings whose elemental expressions took radically different paths from the exact same parents.\n\nRahim is what happens when Fire and Water become life, hunger, and blood.\n\nIfe is what happens when Fire and Water achieve equilibrium.\n\nRahim''s disappearance deeply affects her.\n\nFor someone who defines herself through protecting family, having her own brother disappear without being able to prevent it represents one of Ife''s greatest emotional wounds.\n\nShe has not stopped caring about what happened to him.\n\nRuchika — Maternal Half-Brother\n\nRelationship: Older maternal half-brother\nShared Parent: Leviathans\nOther Parent: Terrax\nDragon Element: Bone\nTitle: The Bone Dragon\n\nRuchika and Ife share a particularly tangible sibling bond.\n\nRuchika created Ife''s Bone Dragon Whip specifically for her.\n\nThe weapon is modeled after his own tail-bone structure and carries his Bone magic within it.\n\nFor Ife, this means she effectively carries something representing her brother into every major battle.\n\nThe weapon''s self-repairing nature reinforces that symbolism.\n\nIt breaks.\n\nIt returns together.\n\nIt survives.\n\nTheir relationship carries a strong protective quality, although both express protection differently.\n\nRuchika gave his sister a weapon capable of protecting herself when he cannot physically be beside her.\n\nIfe treats the Bone Dragon Whip accordingly.\n\nSomeone carelessly touching or disrespecting it is one of the fastest ways to irritate her.\n\nEzra — Paternal Half-Brother\n\nRelationship: Paternal half-brother\nShared Parent: Ignis\nOther Parent: Aetheros\nDragon Element: Lightning\nTitle: The Sapphire Dragon\n\nEzra brings out a more competitive side of Ife.\n\nHe is energetic, flashy, prideful, fast, and naturally confident in his own abilities.\n\nIfe is considerably quieter.\n\nThis makes their sibling dynamic entertaining.\n\nEzra may announce exactly how impressive his newest technique is.\n\nIfe may simply look at him and ask whether he is finished.\n\nTheir elemental abilities also create interesting sparring matches.\n\nLightning favors speed and sudden overwhelming attacks.\n\nSteam favors obscuration, containment, and battlefield control.\n\nEzra can be extremely difficult for Ife to catch.\n\nIfe can make the battlefield increasingly miserable for Ezra to navigate.\n\nTheir rivalry is primarily familial and competitive rather than hostile.\n\nRegardless of how much they irritate one another, an outside threat against one sibling immediately changes the other''s behavior.\n\nAshóNodia “Ash” — Paternal Half-Brother\n\nRelationship: Younger paternal half-brother\nShared Parent: Ignis\nOther Parent: Hecate\nDragon Element: Ash\nTitle: The Ash Dragon\nCurrent Relationship Status: Unknown to Ife\n\nThis is currently Ife''s most important hidden sibling relationship.\n\nAsh is her brother.\n\nIfe does not know he exists.\n\nShe therefore has no established personal relationship with him yet.\n\nThat absence is intentional and important.\n\nIf Ife eventually discovers the truth, Ash presents a difficult emotional situation for her.\n\nHer first instinct would likely be protective.\n\nHer second could be guilt.\n\nNot because she actually failed him—but because Ife has a tendency to feel responsible for people she loves.\n\nLearning that a younger brother existed and experienced major hardships without her knowing could provoke the immediate thought:\n\n“Where was I?”\n\nThe answer is simple.\n\nShe did not know.\n\nAccepting that she cannot protect someone from circumstances she never knew existed could become an important part of her development.\n\nTheir eventual relationship should therefore be allowed to develop naturally rather than immediately becoming perfect simply because they share blood.","worldConnections":"Ignis Peaks\n\nConnection: Primary home\n\nIfe lives within Moltenmaw Caverns and is deeply connected to the inhabitants and culture of her father''s elemental domain.\n\nMoltenmaw Caverns\n\nConnection: Residence\n\nHer primary home within the Ignis Peaks.\n\nThe Sunna\n\nConnection: Personal sanctuary\n\nThe massive lava pool belonging to Ignis has become one of Ife''s favorite resting places.\n\nShe frequently sleeps beneath its surface.\n\nSunken Dominion\n\nConnection: Maternal ancestral realm\n\nThrough Leviathans, Ife possesses bloodline and elemental ties to the waters of the world and their inhabitants.\n\nTerrax\n\nConnection: Extended family\n\nRuchika''s father, Terrax, connects Ife indirectly to the Earth Primordial branch of the family.\n\nAetheros\n\nConnection: Extended family\n\nEzra''s mother, Aetheros, connects Ife indirectly to the Air Primordial branch.\n\nThe Wider Primordial Family\n\nIfe occupies an unusually central position within the elemental family tree.\n\nHer immediate relationships connect her to:\n\nFire — Ignis\n\nWater — Leviathans\n\nEarth — through Ruchika and Terrax\n\nAir — through Ezra and Aetheros\n\nBlood — Rahim\n\nBone — Ruchika\n\nLightning — Ezra\n\nAsh — AshóNodia\n\nThis makes Ife one of the strongest relational bridges between the different Primordial Dragon branches.","relationshipNotes":"Ife''s relationships are fundamentally shaped by one trait:\n\nShe protects people.\n\nBut she does not express affection identically with everyone.\n\nWith Ignis\n\nLove often appears through combat, teasing, endurance, and simply spending time in the same space.\n\nWith Leviathans\n\nThe relationship is quieter and more fluid, reflecting patience, understanding, and Ife''s connection to the other half of her elemental identity.\n\nWith Rahim\n\nProtection becomes worry.\n\nHis disappearance represents something Ife cannot simply solve with strength.\n\nWith Ruchika\n\nProtection becomes trust.\n\nThe Bone Dragon Whip physically represents that bond.\n\nWith Ezra\n\nAffection frequently disguises itself as irritation and competition.\n\nThey can annoy each other tremendously while remaining fiercely loyal siblings.\n\nWith Ash\n\nThere is currently only an unknown blood connection.\n\nThe relationship itself has not begun yet.\n\nThat distinction is important.\n\nBlood may make Ash her brother.\n\nIt does not automatically create trust, familiarity, or emotional intimacy.\n\nThose things must develop after they meet.\n\nIfe''s Relationship Pattern\n\nIfe tends to become the guardian within relationships.\n\nShe remembers people''s needs.\n\nShe notices danger.\n\nShe intervenes.\n\nShe places herself between threats and people she loves.\n\nBut this creates one recurring problem:\n\nIfe is much better at protecting people than allowing people to protect her.\n\nHer strongest relationships will eventually challenge that habit.\n\nThe people closest to Ife should not merely become individuals standing behind her protection.\n\nThey should become the people willing to step forward and stand beside her.\n\nThat distinction is essential to her emotional development.\n\nIfe begins with:\n\n“Stay behind me.”\n\nHer healthiest relationships eventually teach her:\n\n“Stand beside me.”"},"spoiler_level":"private","race_record_id":"1ec72d01-822b-4992-9434-7772a6b4e474","realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":null}','2026-09-25T16:39:57.793622+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('21bb847e-78c1-44ee-b00a-df0a2a003c93','studio_characters','894e397e-74b8-492b-98f3-3ff79811f9b2','Nysera Sylvaris','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"894e397e-74b8-492b-98f3-3ff79811f9b2","name":"Nysera Sylvaris","media":{"tbdFields":"","canonLocks":"Full Sylvani Elf\nShailara''s maternal sister\nTerrax is not her father\nBrown and icy-blue heterochromia\nNear-black and dark-brown hair\nNo Sunspear-Indian attributes\nDark earthy nature magic\nLives in Eldoria","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"","visualAssets":"","productionNotes":"","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Nysera Sylvaris","race":"Elf","alias":"The Wild Root","gender":"Female","titles":"The Wild Root\nKeeper of the Hollow Groves","subrace":"Sylvani Elf","summary":"A full-blooded Sylvani Elf of Eldoria and Shailara''s maternal sister. Nysera is hyperactive, feisty, fiercely independent, and deeply attached to Shailara. Her magic manifests through the darker, untamed aspects of earth and nature.","heritage":"Sylvani","homeland":"Eldoria","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"Sylvani Elves","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Eldoria","elementalHeritage":""},"abilities":{"weapons":"Briarfang","strengths":"Fast reactions\nUnpredictable movement\nEnvironmental control\nAdaptive combat","weaknesses":"","combatStyle":["Chaotic","Agile","Improvised","Acrobatic"],"limitations":"","powerSource":["Sylvani Arcane Magic","Nature Magic"],"abilityNotes":"Nysera''s magic represents the darker and more untamed side of nature. Its earthy character manifests through roots, thorns, shadowed vegetation, fungi, and natural decay rather than Terrax''s draconic earth power.","combatProfile":"Nysera fights with aggressive, unpredictable movement rather than formal elegance. She combines mobility with roots, thorns, vegetation, and surrounding terrain to pressure opponents from changing angles.","weaponDetails":"Briarfang is a living weapon formed from enchanted dark roots. It can shift between several combat configurations.","transformations":"","primaryAbilities":"Dark Earth Magic\nRoot Manipulation\nThorn Manipulation\nVegetation Manipulation","secondaryAbilities":"Fungal Manipulation\nDecay Manipulation","signatureTechniques":"Gravebloom\nThornshade Forest","transformationDetails":""},"is_public":false,"appearance":{"build":"","nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Brown","Icy blue"],"grooming":"","skinTone":"","wardrobe":"","hairColor":["Near-black","Dark brown"],"hairStyle":"","accessories":"","faceDetails":["Elegant Sylvani features","High cheekbones","Pointed ears"],"hairTexture":"","colorPalette":"","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"","appearanceNotes":"Nysera resembles Shailara through their shared Sylvani maternal features, but lacks Shailara''s Sunspear-Indian traits. Her heterochromia gives her one brown eye and one icy-blue eye.","outfitMaterials":"","postureMovement":["Restless","Energetic","Quick-moving"],"signatureOutfit":"","distinguishingFeatures":["Heterochromia"]},"created_at":"2026-09-25T16:42:21.408048+00:00","updated_at":"2026-09-25T16:42:21.408048+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":"","culture":["Sylvani"],"lineage":"Sylvani Elf","storyArc":"","backstory":"Nysera was born a full Sylvani Elf and lives among her people in Eldoria. She shares her mother with Shailara but has no blood relation to Terrax. She developed an unusually dark, earthy expression of traditional Sylvani nature magic.","childhood":"","lifestyle":"","storyRole":"","birthplace":"Eldoria","psychology":["Deeply attached to Shailara","Dislikes being controlled","Challenges authority"],"motivations":["Protect Shailara","Preserve her independence"],"personality":["Hyperactive","Feisty","Defiant","Stubborn","Independent","Protective","Argumentative","Energetic"],"voiceSpeech":["Quick-spoken","Sharp-tongued","Frequently talks back"],"likesDislikes":["Loves Shailara","Dislikes being ordered around","Dislikes backing down"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"Shailara","worldConnections":"Eldoria","relationshipNotes":"Nysera and Shailara share the same Sylvani mother but have different fathers. Nysera idolizes Shailara and is intensely protective of her. Terrax is not Nysera''s father."},"spoiler_level":"private","race_record_id":"e51921b8-4241-49df-9b95-af8af0c669b2","realm_record_id":"291c05cb-0705-495d-95be-c6037453f9b4","workflow_status":"draft","family_record_id":"74ad83da-fab3-4afc-ad5a-4a9c23f4272f","faction_record_id":"ec63b03d-99da-41ec-8596-cb819b74c195"}','2026-09-25T16:47:08.281296+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('e349f8f1-1887-46c4-8b88-1a5a3f21cfcd','studio_characters','258ae7f1-bd63-4538-960d-9d0a5f0f1200','Nysera Sylvaris','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"258ae7f1-bd63-4538-960d-9d0a5f0f1200","name":"Nysera Sylvaris","media":{"tbdFields":"","canonLocks":"Pure Sylvani Elf\nStrong resemblance to Shailara\nAmber-brown left eye\nGlacial icy-blue right eye\nLong wild dark-brown hair\nMoss-green hair highlights\nLight bronze skin\nVine-like markings\nDark emerald marking glow\nBriarfang","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done","productionNotes":"Preserve Nysera''s strong facial resemblance to Shailara while maintaining her fully Sylvani identity and wilder visual language. Her heterochromia, dark wild hair, moss-green highlights, light bronze skin, and vine-like markings are essential visual identifiers.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Nysera Sylvaris","race":"Sylvani Elf","alias":"The Wild Root","gender":"Female","titles":"The Thornheart Elf\nThe Shadow of Eldoria\nKeeper of the Hollow Groves\nBeloved Sister of Shailara, The Living Mountain","subrace":"","summary":"Nysera Sylvaris is a pure Sylvani Elf known as the Wild Root and Keeper of the Hollow Groves. Where Shailara embodies calm growth and sheltering nature, Nysera represents nature''s untamed, darker will. Her chaotic temperament and forbidden-feeling Hollow Root magic make her both a troublesome presence and a potential guardian of Eldoria.","heritage":"Sylvani","homeland":"Eldoria","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Eldoria","elementalHeritage":""},"abilities":{"weapons":"Briarfang","strengths":"Unpredictable combat\nEnvironmental control\nExceptional mobility\nImprovisation\nMagical energy draining\nAdaptive weapon use","weaknesses":"","combatStyle":["Wild","Chaotic","Improvised","Acrobatic","Feral"],"limitations":"","powerSource":["The Hollow Root","Sylvani nature magic"],"abilityNotes":"The Hollow Root governs the neglected and darker aspects of nature rather than conventional nurturing growth. Gravebloom causes black flowers to erupt from the ground and drain magical energy, with stronger opponents producing larger blooms. Thornshade Forest transforms the surrounding area into black trees, twisting roots, glowing fungi, and dark vines that obey Nysera.","combatProfile":"Nysera fights more like a feral woodland spirit than a Sylvani noble. She jumps, spins, climbs, and exploits the environment while using roots for sudden movement and unconventional attacks. Her unpredictability makes her difficult to read in battle.","weaponDetails":"Briarfang is a living weapon formed from enchanted black roots. It can transform between whip, spear, bow, and blade configurations according to Nysera''s needs and mood.","transformations":"","primaryAbilities":"Dead Forest Manipulation\nBlack Root Manipulation\nFungal Manipulation\nThorn Growth\nDecay Cycle Manipulation\nShadowed Vegetation Manipulation","secondaryAbilities":"Root Mobility\nRoot Slingshot Movement\nVegetation Command","signatureTechniques":"Gravebloom\nThornshade Forest","transformationDetails":""},"is_public":false,"appearance":{"build":"","nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Amber-brown left eye","Glacial icy-blue right eye"],"grooming":"Wild and natural","skinTone":["Light bronze"],"wardrobe":"","hairColor":["Dark brown","Near-black undertones","Moss-green highlights"],"hairStyle":"Long, wild, usually unbrushed","accessories":"","faceDetails":["Elegant jawline","High cheekbones","Graceful Sylvani features"],"hairTexture":"","colorPalette":"Dark brown\nNear-black\nMoss green\nDark emerald\nAmber-brown\nIcy blue","dominantHand":"","outfitColors":"","alternateForm":"","clothingStyle":"","appearanceNotes":"Nysera strongly resembles Shailara, sharing the same elegant facial structure and graceful Sylvani features. Outsiders sometimes mistake them for twins or assume they share the same father, which secretly delights Nysera. Her moss-green hair streaks become visible in sunlight, while her vine-like markings glow dark emerald when she channels magic.","outfitMaterials":"","postureMovement":["Restless","Energetic","Acrobatic","Feral"],"signatureOutfit":"","distinguishingFeatures":["Heterochromia","Faint vine-like markings","Pointed Sylvani ears"]},"created_at":"2026-09-25T16:41:56.717031+00:00","updated_at":"2026-09-25T16:41:56.717031+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Decay is part of nature","Untamed nature deserves protection"],"culture":["Sylvani"],"lineage":"Pure Sylvani","storyArc":"","backstory":"Nysera inherited no Terrax blood and is entirely Sylvani. Despite this, her strong resemblance to Shailara frequently causes outsiders to assume the sisters share the same father. Her unusual connection to the darker cycles of nature distinguishes her from traditional Sylvani and leaves Eldoria''s elders divided over what she may become.","childhood":"","lifestyle":["Climbs constantly","Explores wild places","Rarely sits still"],"storyRole":"Nysera serves as Eldoria''s unpredictable troublemaker and a possible future guardian. Her connection to neglected and feared aspects of nature challenges traditional Sylvani ideas about what natural magic should be.","birthplace":"Eldoria","psychology":["Idolizes Shailara","Constantly seeks stimulation","Enjoys pushing back","Intensely loyal"],"motivations":["Protect Shailara","Defend untamed nature","Follow her own instincts"],"personality":["Hyperactive","Feisty","Stubborn","Protective","Reckless","Talented","Argumentative","Distractible"],"voiceSpeech":["Energetic","Argumentative","Blunt"],"likesDislikes":["Collecting flowers Shailara touched","Sketching Shailara","Bragging about Shailara","Dislikes insults toward Shailara","Dislikes being told no"],"majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"Shailara","worldConnections":"Eldoria","relationshipNotes":"Nysera intensely adores and idolizes Shailara. She collects flowers Shailara has touched, keeps sketches of her, constantly brags about her, and readily starts fights when someone insults her. Shailara is one of the few people capable of calming Nysera down."},"spoiler_level":"private","race_record_id":"76da8c54-5f55-4b33-b807-02e8eb74e869","realm_record_id":"291c05cb-0705-495d-95be-c6037453f9b4","workflow_status":"draft","family_record_id":"00ba4f50-602d-4833-9eae-2ce8c18297e6","faction_record_id":null}','2026-09-25T16:47:10.904869+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('d7810ae8-1f4b-4ac0-a79f-8798d85da4c9','studio_characters','6358b47b-ec0c-4027-b539-5334a350b2ff','Count Vex','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"6358b47b-ec0c-4027-b539-5334a350b2ff","name":"Count Vex","media":{"tbdFields":"","canonLocks":"","galleryUrl":"","mediaNotes":"","galleryUrls":[],"portraitUrl":"","visualAssets":"","productionNotes":"","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"Late 30s to early 40s","era":"","name":"Count Vex","race":"","alias":"The Iron Smile","gender":"Male","titles":"Grand Inquisitor of Shadowfen","subrace":"","summary":"Count Vex is the Grand Inquisitor of Shadowfen, known as the Iron Smile. Refined, controlled, and intimidating, he carries himself like a judge who has already reached a verdict. His immaculate appearance and quiet authority make every encounter feel like a formal trial.","heritage":"","homeland":"","pronouns":"He/Him","birthDate":"","nicknames":"","occupation":"Grand Inquisitor","affiliation":"Shadowfen","apparentAge":"","canonStatus":"Canon","nameMeaning":"","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"Shadowfen","elementalHeritage":""},"abilities":{"weapons":"Ceremonial Rapier","strengths":"","weaknesses":"","combatStyle":["Dueling"],"limitations":"","powerSource":"","abilityNotes":"Mass Fear Projection creates an overwhelming sensation of judgment and guilt. Those affected describe the experience as feeling as though the world itself has decided they are guilty.","combatProfile":"Vex has the lean, athletic physique of a duelist rather than a brute. His known weapon is an ornate ceremonial rapier.","weaponDetails":"An ornate ceremonial rapier carried as part of Vex''s refined inquisitorial appearance.","transformations":"Mass Fear Projection State","primaryAbilities":"Mass Fear Projection","secondaryAbilities":"","signatureTechniques":"","transformationDetails":"When Mass Fear Projection activates, Vex''s pupils narrow into thin vertical slits and dark veins spread around his eyes."},"is_public":false,"appearance":{"build":["Lean","Athletic","Duelist-built"],"nails":"","eyeHex":"","height":"6''3\"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Pale steel gray"],"grooming":"Immaculate","skinTone":["Pale"],"wardrobe":"Military dress coats\nWhite gloves\nCrimson mantles","hairColor":["Dark silver","Platinum blond"],"hairStyle":"Perfectly slicked back","accessories":"White gloves\nShadowfen insignia","faceDetails":["Sharp aristocratic face","High cheekbones","Long nose","Narrow eyes","Cold smile"],"hairTexture":["Straight","Smooth"],"colorPalette":"Black\nSilver\nWhite\nCrimson","dominantHand":"","outfitColors":"Black\nSilver\nWhite\nCrimson","alternateForm":["Mass Fear Projection State"],"clothingStyle":"Extremely refined military formalwear with aristocratic and ceremonial details.","appearanceNotes":"Vex treats his appearance as a weapon. His clothing, hair, posture, and grooming remain meticulously controlled because he considers imperfection a weakness. During Mass Fear Projection, his pupils become thin vertical slits and dark veins spread around his eyes.","outfitMaterials":"","postureMovement":["Controlled","Elegant","Deliberate"],"signatureOutfit":"Black military dress coat with silver embroidery, white gloves, and a long crimson mantle.","distinguishingFeatures":["Perpetually unimpressed expression","Immaculate grooming"]},"created_at":"2026-09-25T16:44:05.635265+00:00","updated_at":"2026-09-25T16:44:05.635265+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Imperfection equals weakness"],"culture":"","lineage":"","storyArc":"","backstory":"","childhood":"","lifestyle":["Meticulous grooming","Strict personal presentation"],"storyRole":"Grand Inquisitor of Shadowfen.","birthplace":"","psychology":["Views imperfection as weakness","Maintains strict self-control"],"motivations":"","personality":["Cold","Refined","Controlled","Judgmental","Intimidating","Aristocratic","Unimpressed"],"voiceSpeech":["Quiet","Controlled","Formal"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"","partner":"","children":"","siblings":"","worldConnections":"","relationshipNotes":""},"spoiler_level":"private","race_record_id":null,"realm_record_id":null,"workflow_status":"draft","family_record_id":null,"faction_record_id":"74fb0163-f452-4f7e-a9ea-13c15bb960db"}','2026-09-25T16:55:01.168335+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('e52ac21f-c322-497f-b214-b2ba66fd40a4','studio_characters','e3ed8aa4-6a04-4790-9eff-6a0c06066e35','Ife','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"e3ed8aa4-6a04-4790-9eff-6a0c06066e35","name":"Ife","media":{"tbdFields":"Birth date\nExact chronological age\nWeight\nNationality\nPartner\nChildren\nNamed non-family allies\nNamed personal enemies","canonLocks":"Deep warm-brown skin\nCosmic pink eyes\nNatural black 4C hair\nLong decorated braids\nAthletic-curvaceous build\nSteam Rose signature color\nBronze and copper accessories\nBone Dragon Whip\nPink Steam Dragon true form\nIridescent wing membranes\nSteam and bubble magic","galleryUrl":"","mediaNotes":"Maintain visual continuity across all future artwork and 3D models. Pink should remain Ife''s dominant supernatural color, supported by bronze, copper, violet, pearl, and subtle iridescent blue.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done\nBone Dragon Whip Reference — Done\nVRoid Turnaround Reference — Done\nBlender Model Reference — Done","productionNotes":"Use the established Reference / Production Sheet as the primary visual guide. Preserve Ife''s deep warm-brown complexion, cosmic pink eyes, long decorated 4C braids, athletic-curvaceous build, pink steam-woven clothing, bronze jewelry, and pink-centered elemental effects.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"500–1300 AD-inspired","name":"Ife","race":"Half-Primordial Dragon","alias":"The Pink Steam Dragon","gender":"Female","titles":"Daughter of Fire and Water\nProtector of the Scalding Gardens\nThe Steam-Born Guardian","subrace":"Steam Dragon","summary":"Ife is the Pink Steam Dragon, born from the union of Ignis and Leviathans. Fire and Water combine within her as Steam, giving her command over superheated vapor, pressure, condensation, and supernatural bubbles. Quiet and protective by nature, she specializes in defending others and controlling the battlefield.","heritage":"African + Asian","homeland":"Ignis Peaks","pronouns":"She/Her","birthDate":"","nicknames":"Pink Steam","occupation":"Elemental Guardian","affiliation":"Ignis Peaks","apparentAge":"Young adult","canonStatus":"Canon","nameMeaning":"Love","nationality":"","spoilerLevel":"","pronunciation":"EE-feh","currentResidence":"Moltenmaw Caverns","elementalHeritage":"Fire + Water"},"abilities":{"weapons":"Bone Dragon Whip","strengths":"Battlefield control\nDefensive versatility\nThermal resistance\nPressure manipulation\nEnvironmental adaptability\nWeapon synergy\nHigh elemental output\nProtective focus","weaknesses":"Extreme cold\nMoisture-depleted environments\nOverpressure\nProtective exploitation\nEmotional pressure","combatStyle":["Defensive zoning","Battlefield control","Mid-range whip combat","Containment","Counterattacking","Circular movement"],"limitations":["Steam requires elemental balance","Bubble durability is finite","Large bubbles consume more energy","Pressure releases can endanger allies","Large-scale techniques require concentration","Dragon form increases energy consumption"],"powerSource":["Primordial elemental bloodline","Fire","Water","Steam"],"abilityNotes":"Steam is Ife''s unique elemental identity rather than separate Fire and Water spellcasting. Fire manifests primarily as heat, Water as moisture and condensation, and their equilibrium produces Steam. Her bubbles act as supernatural pressure membranes capable of defense, containment, transportation, and storing extreme heat or pressure.","combatProfile":"Ife controls space through her Bone Dragon Whip, steam fields, reinforced bubbles, and pressure attacks. She prefers to contain threats, protect allies, and punish attempts to breach her defensive perimeter. Her fighting style becomes significantly more destructive when someone under her protection is threatened.","weaponDetails":"Ruchika crafted the Bone Dragon Whip from a replica of his own tail-bone structure. Its articulated bone segments are flexible, heat-resistant, self-repairing, and attuned to Ife. She can channel superheated steam through its internal structure for binding, striking, and pressure-based attacks.","transformations":"Pink Steam Dragon\nSteam Surge\nPressure-Crowned Dragon State","primaryAbilities":"Superheated Steam Generation\nSteam Manipulation\nBubble Sorcery\nThermal Pressure Manipulation\nExtreme Thermal Resistance\nElemental Condensation","secondaryAbilities":"Steam Veil\nHeat Shimmer\nBubble Platforms\nSteam Propulsion\nPressure Detection\nCondensation Tracking\nLava Encapsulation","signatureTechniques":"Steam Lash\nScalding Bind\nPressure Spike\nSteam Whip Cyclone\nBubble Prison\nGuardian Bubble\nPinkout\nScalding Garden\nLava Bloom\nScalding Veil","transformationDetails":"Ife''s true form is a massive deep rose-pink Steam Dragon with translucent underlayers, obsidian-edged markings, cosmic pink eyes, and iridescent bubble-film wing membranes. Her transformation is concealed within rapidly expanding steam as scales, claws, tail, and wings emerge. Pressure-Crowned Dragon State is a high-output state of her true form rather than a separate transformation."},"is_public":false,"appearance":{"build":["Athletic","Curvaceous","Strong thighs","Defined shoulders","Hourglass proportions"],"nails":["Almond-shaped","Dusty rose","Deep rose accents","Pearl highlights"],"eyeHex":["Main Iris Pink — #E75C9A","Deep Iris — #8E285E","Light Iris Pink — #FF8FC5","Galaxy Violet — #9C68D7","Magical Glow — #FFD0EA","Outer Iris Ring — #6F204E","Hot-Pink Ring — #FF72B6","Pupil — #291224"],"height":"5''8\" / 173 cm","makeup":["Burnt rose blush","Deep plum eyeshadow","Rose mauve eyeshadow","Iridescent pink eyelids","Pearl-pink eye highlights","Black-plum eyeliner","Smoky burgundy lower lash","Deep berry-brown lip liner","Burnt rose lips","Bubble-pearl lip highlight"],"weight":"","hairHex":["Primary Hair — #171116","Warm Black — #24191D","Brown Highlight — #49302F","Pink Reflection — #8B405F"],"skinHex":["Deep Mahogany — #6B3B32","Warm Brown — #805044","Warm Highlight — #A96E5D","Bright Highlight — #C58B78","Shadow — #45241F","Deep Shadow — #2A1615"],"eyeColor":["Cosmic pink","Iridescent pink-violet"],"grooming":"Meticulous hair, skin, jewelry, and clothing care.","skinTone":["Deep warm brown","Reddish-mahogany undertone"],"wardrobe":"Ignis Peaks casual wear\nSunna resting attire\nCombat attire\nCeremonial attire\nSunken Dominion attire","hairColor":["Natural black"],"hairStyle":"Long decorated braids with a raised braided crown and bun.","accessories":"Bronze hoop earrings\nPink gemstone earrings\nForehead jewelry\nHead chains\nHair rings\nPink hair beads\nBronze braid cuffs\nLayered necklaces\nChoker\nUpper-arm cuffs\nBracelets\nWrist cuffs\nWaist chains\nDecorative belt\nHip chains\nAnklets\nPink gemstones","faceDetails":["Softly angular oval face","High cheekbones","Defined jawline","Full lips","Softly broad nose","Almond-shaped eyes","Thick natural eyebrows","Long dark eyelashes"],"hairTexture":["4C","Dense","Tightly coiled"],"colorPalette":"Deep Mahogany — #6B3B32\nWarm Brown — #805044\nDragon Black — #171116\nSteam Rose — #C77B91\nCosmic Pink — #E75C9A\nBubble Blush — #E5A7B8\nSteam Pearl — #F2CAD5\nPressure Rose — #87485F\nBubble Violet — #9C68D7\nBubble Blue — #82C9DF\nDragon Bronze — #9B633B\nMolten Copper — #B96E46\nSteam Gold — #D9A568\nVolcanic Black — #21191C","dominantHand":"Right","outfitColors":"Dusty Steam Pink — #C77B91\nLight Rose — #E5A7B8\nPearl Pink — #F2CAD5\nDeep Rose — #87485F\nWarm Cream — #E8D3C0\nBronze — #9B633B\nCopper — #B96E46\nGold — #D9A568\nPink Gemstone — #D9568D\nBubble Violet — #B894E8\nBubble Blue — #82C9DF","alternateForm":["Pink Steam Dragon"],"clothingStyle":"Flowing early-medieval fantasy attire influenced by African and Sahelian silhouettes. Draped fabrics, split panels, wrapped garments, metallic body jewelry, and translucent steam-woven textiles emphasize movement and bubble motifs.","appearanceNotes":"Ife''s design visually balances Fire and Water through warm skin, bronze metals, flowing fabrics, iridescence, moisture, and translucent bubble motifs. Pink is her dominant supernatural color. Her magical activity increases the visibility of steam, bubbles, iridescent markings, and heat distortion.","outfitMaterials":["Steam-woven alchemical silk","Translucent magical fibers","Bronze","Copper","Pink gemstones"],"postureMovement":["Upright","Composed","Fluid","Deliberate","Circular combat movement"],"signatureOutfit":"A wrapped pink upper garment with layered asymmetrical skirt panels, translucent steam-woven fabric, a decorated metallic belt, and bronze body jewelry.","distinguishingFeatures":["Cosmic pink irises","Long decorated braids","Pink steam aura","Iridescent power markings","Heat shimmer"]},"created_at":"2026-09-25T16:39:50.039916+00:00","updated_at":"2026-09-25T16:39:50.039916+00:00","is_complete":true,"origin_lore":{"fears":["Failing to protect loved ones","Losing family","Losing emotional control"],"goals":["Master Steam magic","Understand her dual heritage","Find answers about Rahim","Protect without controlling"],"beliefs":["Strength should protect","Opposing forces can coexist","Power requires purpose","Balance creates strength"],"culture":["Ignis Peaks","Sunken Dominion","Primordial Dragonkin"],"lineage":"Primordial Fire and Water bloodline","storyArc":"Ife''s arc explores the difference between protecting others and believing she is responsible for everything that happens to them. Rahim''s disappearance challenges her belief that sufficient strength can always keep family safe. Her eventual discovery of Ash further forces her to accept that she cannot protect someone from circumstances she never knew existed.","backstory":"Born to Ignis and Leviathans, Ife emerged as a natural equilibrium between Fire and Water. Rather than inheriting two separate elemental disciplines, their opposing forces fused within her as Steam. She grew into a protective fighter who favors containment and defense, later receiving the Bone Dragon Whip from Ruchika. Rahim''s disappearance remains an unresolved emotional wound, while the existence of Ash remains unknown to her.","childhood":"Ife grew up within Moltenmaw Caverns, where volcanic heat and lava were natural parts of everyday life. She developed a strong attachment to the Sunna and learned early that she could sleep beneath its molten surface. Her childhood training focused heavily on controlling the heat, moisture, and pressure generated by her Steam Dragon physiology.","lifestyle":["Lives in Moltenmaw Caverns","Sleeps beneath the Sunna","Maintains her braids","Maintains her weapon","Practices steam control","Trains with family","Enjoys solitude"],"storyRole":"Ife serves as an Elemental Guardian and relational bridge between multiple Primordial bloodlines. Her Fire and Water heritage places her near the center of the wider elemental family while her protective nature makes her a stabilizing presence during conflict.","birthplace":"Moltenmaw Caverns","psychology":["Protective instinct","Strong emotional restraint","Over-responsibility","Difficulty accepting protection","Need for stability"],"motivations":["Protect her family","Protect the vulnerable","Maintain balance"],"personality":["Warm","Reserved","Observant","Protective","Dependable","Patient","Practical","Family-oriented","Responsible","Quietly affectionate","Stubborn"],"voiceSpeech":["Warm medium-low voice","Measured speech","Direct wording","Dry humor","Quiet when angry"],"likesDislikes":["Likes extreme warmth","Likes hot springs","Likes steam","Likes rain on warm stone","Likes quiet mornings","Likes family gatherings","Likes routine","Likes jewelry","Likes bubbles","Likes swimming","Dislikes needless cruelty","Dislikes betrayal","Dislikes reckless endangerment","Dislikes unnecessary chaos","Dislikes bullying"],"majorLifeEvents":"Birth of the Pink Steam Dragon\nChildhood in Moltenmaw Caverns\nDiscovery of the Sunna\nMastery of Bubble Sorcery\nTraining under Ignis\nReceiving the Bone Dragon Whip\nRahim''s disappearance"},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"Ezra","enemies":"","mentors":"Ignis\nLeviathans\nRuchika","parents":"Ignis\nLeviathans","partner":"","children":"","siblings":"Rahim\nRuchika\nEzra\nAsh","worldConnections":"Ignis Peaks\nMoltenmaw Caverns\nSunken Dominion\nSunna","relationshipNotes":"Ife is deeply family-oriented and often assumes a protective role around those she loves. Rahim''s disappearance remains a major emotional wound. Ruchika created her Bone Dragon Whip, while Ezra shares a competitive sibling rivalry with her. Ife does not currently know that Ash exists."},"spoiler_level":"private","race_record_id":"2f59d6e1-b234-4fd6-b00c-5db6d8144fff","realm_record_id":"97d4dc51-d1bf-4f80-9e77-3955ba9dad35","workflow_status":"draft","family_record_id":"08d087d1-5f3c-4b76-9ee9-2917fe667bf1","faction_record_id":"406ddfbf-feab-4b20-9026-bd74b716fbda"}','2026-09-25T17:05:23.889833+00:00');
INSERT OR IGNORE INTO studio_revisions (id,entity_type,entity_id,entity_label,changed_by,changed_by_email,snapshot,created_at) VALUES ('a7af6901-348f-4aeb-a53e-15a5c0637d97','studio_characters','bc34fdb8-22a5-439b-8067-e5b670626b0f','Shailara','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com','{"id":"bc34fdb8-22a5-439b-8067-e5b670626b0f","name":"Shailara","media":{"tbdFields":"Birth date\nAge\nHeight\nWeight\nBirthplace\nCurrent residence\nOccupation\nMother''s name","canonLocks":"Warm bronze-brown skin\nJade green eyes\nDark brown hair\nEmerald hair undertones\nPointed Sylvani ears\nLiving vines in hair\nNatural flowers in hair\nForest-green signature outfit\nEmerald crystal motifs\nLiving stone dragon form","galleryUrl":"","mediaNotes":"Established visual references include Shailara''s human portrait, Earth Dragon form, and full visual production sheet.","galleryUrls":[],"portraitUrl":"","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nAlternate / True Form — Done","productionNotes":"Preserve the established human and dragon designs. Her visual identity should consistently combine stone, emerald crystal, living vegetation, refined Sylvani elements, and Sunspear Indian heritage.","referenceArtUrl":"","alternateFormUrl":""},"status":"complete","user_id":"db618e68-0656-4b9b-b308-81e071faf745","identity":{"age":"","era":"","name":"Shailara","race":"Half Earth Dragon / Half Sylvani Elf","alias":"The Living Mountain","gender":"Female","titles":"The Living Mountain\nKeeper of the Emerald Vein","subrace":"","summary":"Shailara is the daughter of Terrax, an Earth Dragon of Sunspear Indian heritage, and a Sylvani Elf deeply connected to nature and traditional arcane magic. Known as the Living Mountain, she embodies a rare union of ancient stone and living nature. Her earth-dragon power manifests through the Emerald Vein, allowing stone, crystal, roots, and vegetation to exist as parts of the same living system.","heritage":"Indian + Sylvani Elf","homeland":"","pronouns":"She/Her","birthDate":"","nicknames":"","occupation":"","affiliation":"","apparentAge":"","canonStatus":"Canon","nameMeaning":"Stone Blossom","nationality":"","spoilerLevel":"","pronunciation":"","currentResidence":"","elementalHeritage":"Earth + Sylvani"},"abilities":{"weapons":"","strengths":"Earth manipulation\nEnvironmental restoration\nDefensive durability\nTerrain control\nNature synergy","weaknesses":"","combatStyle":["Terrain control","Defensive combat","Environmental manipulation"],"limitations":"","powerSource":["Earth Dragon heritage","Sylvani magic","Emerald Vein"],"abilityNotes":"The Emerald Vein unifies Shailara''s earth and Sylvani inheritances, allowing stone and plant life to function together. Her Lithobloom Core causes vegetation to grow naturally from her draconic body and allows her presence to encourage ecological renewal.","combatProfile":"Shailara reshapes the battlefield through stone, roots, crystals, and rapidly growing vegetation. Her fighting style emphasizes environmental control and defense rather than reckless aggression. In dragon form, her immense stone body provides exceptional physical durability.","weaponDetails":"","transformations":"Earth Dragon Form","primaryAbilities":"Stone Manipulation\nCrystal Manipulation\nPlant Manipulation\nRoot Manipulation\nLand Restoration","secondaryAbilities":"Accelerated Plant Growth\nCrystal Growth\nLiving Stone Creation\nEcosystem Restoration\nStone-to-Wood Transmutation","signatureTechniques":"Emerald Vein\nLithobloom Core","transformationDetails":"Shailara transforms into a colossal Earth Dragon resembling a living mountain. Her body is covered in layered stone scales with moss, vines, flowers, and emerald crystal formations growing naturally across her frame. Her wings resemble interlocking petrified leaves, stone structures, and crystal branches."},"is_public":false,"appearance":{"build":["Tall","Graceful","Curvaceous"],"nails":"","eyeHex":"","height":"","makeup":"","weight":"","hairHex":"","skinHex":"","eyeColor":["Jade green"],"grooming":"","skinTone":["Warm bronze-brown"],"wardrobe":"Sylvani gowns\nNature-inspired ceremonial attire","hairColor":["Dark brown","Emerald undertones"],"hairStyle":"Long and flowing","accessories":"Emerald forehead jewel\nEmerald earrings\nGold jewelry\nLiving floral ornaments","faceDetails":["Elegant features","High cheekbones","Pointed ears"],"hairTexture":["Thick","Wavy"],"colorPalette":"Granite Grey\nMoss Green\nJade\nEmerald\nOlive\nEarth Brown\nSoft Gold\nIvory\nBlossom Pink","dominantHand":"","outfitColors":"Forest green\nEmerald\nIvory\nSoft gold","alternateForm":["Earth Dragon Form"],"clothingStyle":"Elegant Sylvani clothing blending natural materials, botanical motifs, flowing fabrics, gemstones, and refined ornamentation.","appearanceNotes":"Her human form visibly blends Sunspear Indian and Sylvani features. Living vegetation naturally grows among her hair and clothing. Her dragon form resembles a living mountain composed of layered stone scales, vegetation, vines, flowers, and emerald crystal growths.","outfitMaterials":["Layered fabric","Living vines","Gold ornamentation","Emerald gemstones"],"postureMovement":["Graceful","Composed"],"signatureOutfit":"An elegant forest-green Sylvani gown with botanical detailing, soft flowing ivory fabric, gold ornamentation, emerald accents, and living vines woven naturally through the design.","distinguishingFeatures":["Living vines in hair","Natural flowers in hair","Pointed Sylvani ears"]},"created_at":"2026-09-25T16:49:43.887688+00:00","updated_at":"2026-09-25T16:49:43.887688+00:00","is_complete":true,"origin_lore":{"fears":"","goals":"","beliefs":["Life can return","Stone can nurture growth"],"culture":["Sunspear","Sylvani"],"lineage":"Terrax + Sylvani Elf","storyArc":"","backstory":"Born from an Earth Dragon and a Sylvani Elf, Shailara inherited Terrax''s connection to stone alongside her mother''s affinity for nature and traditional arcane magic. These inheritances developed together rather than remaining separate, producing her unusual bond with living stone.","childhood":"","lifestyle":["Nature-oriented"],"storyRole":"","birthplace":"","psychology":["Values renewal","Protective of nature","Emotionally grounded"],"motivations":["Protect living ecosystems","Restore damaged land","Preserve natural balance"],"personality":["Calm","Nurturing","Patient","Compassionate","Protective","Hopeful"],"voiceSpeech":["Calm","Measured","Gentle"],"likesDislikes":"","majorLifeEvents":""},"canon_status":"concept","current_step":6,"portrait_url":null,"relationships":{"allies":"","rivals":"","enemies":"","mentors":"","parents":"Terrax","partner":"","children":"","siblings":"Nysera","worldConnections":"","relationshipNotes":"Shailara and Nysera share the same Sylvani mother but have different fathers. Nysera is a full Sylvani Elf and is intensely devoted to Shailara."},"spoiler_level":"private","race_record_id":"41d87f15-5819-4dbb-a9db-7abbdc65e92b","realm_record_id":null,"workflow_status":"draft","family_record_id":"e0563851-b12b-4a90-827f-5c38b92a4a58","faction_record_id":null}','2026-09-25T17:11:09.464849+00:00');
